'use strict';
const APP_VERSION='3.9.0';

const $=(s,r=document)=>r.querySelector(s);const $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=(v='')=>String(v).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const money=n=>new Intl.NumberFormat('ru-RU').format(Number(n||0))+' ₽';const num=n=>new Intl.NumberFormat('ru-RU').format(Number(n||0));
const fmtDate=v=>{if(!v)return'—';const d=new Date(String(v).includes('T')?v:String(v)+'T12:00:00');return Number.isNaN(d.getTime())?esc(v):new Intl.DateTimeFormat('ru-RU',{day:'2-digit',month:'2-digit',year:'numeric'}).format(d)};
const fmtDateTime=v=>{if(!v)return'—';const raw=String(v),d=new Date(raw.includes('T')?raw:raw.replace(' ','T'));return Number.isNaN(d.getTime())?esc(raw):new Intl.DateTimeFormat('ru-RU',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'}).format(d)};
const allowedPhotoTypes=new Set(['image/jpeg','image/png','image/webp']);
function fileToDataURL(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file);});}
async function filesToPayload(input){const files=await PhotoInputs.prepare(input);const out=[];for(const f of files)out.push({name:f.name,type:f.type,data:await fileToDataURL(f)});return out;}
function roleLabel(r){return({owner:'Владелец',admin:'Старший менеджер',inspector:'Инспектор',manager:'Менеджер',technician:'Техник',tenant:'Арендатор'}[r]||r);}
function hasPerm(p){return app.user?.role==='owner'||(app.user?.permissions||[]).includes('*')||(app.user?.permissions||[]).includes(p);}
function canManageStaff(){return app.user?.role==='owner';}
function staffMode(){return app.user&&app.user.role!=='tenant';}
function photoGrid(photos=[],showLabel=false){if(!photos.length)return'<div class="photo-empty">Фотографий пока нет</div>';return`<div class="photo-grid">${photos.map(p=>`<div class="saved-photo"><a class="photo-tile" href="${esc(p.url)}" target="_blank" rel="noopener"><img src="${esc(p.url)}" alt="Фото" loading="lazy"><span>${showLabel&&p.label?`<b>${esc(p.label)}</b><br>`:''}${fmtDateTime(p.at)}<br><b>${esc(p.actor||'')}</b></span></a>${canManageStaff()?`<button class="btn btn-ghost danger-link" data-remove-photo="${esc(p.url)}">Удалить фото</button>`:''}</div>`).join('')}</div>`;}
function bindSavedPhotoActions(root){
 $$('[data-remove-photo]',root).forEach(button=>button.onclick=async()=>{
  if(!confirm('Удалить это фото? Действие будет записано в истории.'))return;
  button.disabled=true;const url=button.dataset.removePhoto;
  try{await api(url,{method:'DELETE'});await refresh();const parts=url.split('/');if(parts[2]==='issue-media')openIssue(decodeURIComponent(parts[3]));else openInspection(decodeURIComponent(parts[3]));toast('Фото удалено');}
  catch(err){button.disabled=false;toast(errorText(err));}
 });
}


const statusMap={new:'Новая',assigned:'Назначена',in_progress:'В работе',inspection:'На проверке',overdue:'Просрочена',awaiting_acceptance:'Ожидает подтверждения',done:'Выполнена'};
const priorityMap={low:'Низкий',normal:'Обычный',high:'Высокий',critical:'Критический'};
const inspectionStatusMap={ok:'Норма',attention:'Есть замечания',critical:'Критично'};
const app={user:null,csrf:null,view:'dashboard',data:{},selectedTenant:null,selectedIssue:null};

async function api(url,options={}){const submitting=app.submittingForm;if(submitting&&options.method==='POST'&&options.body&&(url==='/api/equipment'||url==='/api/metrics'||url==='/api/buildings'||url==='/api/tenants'||url==='/api/expenses'||url==='/api/inspections'||url.endsWith('/reports')||url.endsWith('/photos'))){options={...options,body:JSON.stringify({...JSON.parse(options.body),clientRequestId:submitting.dataset.requestId})};}const headers={'Content-Type':'application/json',...(options.headers||{})};if(app.csrf&&options.method&&options.method!=='GET')headers['X-CSRF-Token']=app.csrf;const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),options.body?.length>1_000_000?90000:25000);let r;try{r=await fetch(url,{credentials:'same-origin',...options,headers,signal:controller.signal});}finally{clearTimeout(timeout);}let data={};try{data=await r.json();}catch{}if(r.status===401&&url!='/api/login'){app.user=null;renderLogin();throw new Error('AUTH_REQUIRED');}if(!r.ok){const e=new Error(data.error||'REQUEST_FAILED');e.code=data.error;e.status=r.status;throw e;}if(submitting&&options.method&&options.method!=='GET'&&!url.includes('/notifications/'))FormSafety.markSaved(submitting);return data;}
function toast(t){$$('.toast').forEach(n=>n.remove());const el=document.createElement('div');el.className='toast';el.setAttribute('role','status');el.textContent=t;document.body.appendChild(el);setTimeout(()=>el.remove(),3200);}
let checkingUpdate=false;
async function checkForUpdate(){
 if(checkingUpdate)return;checkingUpdate=true;
 try{const r=await fetch('/version.json',{cache:'no-store'});if(!r.ok)return;const release=await r.json();if(!release.version||release.version===APP_VERSION||$('#appUpdate'))return;
  const banner=document.createElement('div');banner.id='appUpdate';banner.className='app-update';banner.setAttribute('role','status');banner.innerHTML='<span>Доступна новая версия приложения</span><button class="btn btn-primary" id="applyUpdate">Обновить</button><button class="icon-btn" id="dismissUpdate" aria-label="Закрыть уведомление">×</button>';document.body.appendChild(banner);
  $('#dismissUpdate').onclick=()=>banner.remove();$('#applyUpdate').onclick=()=>{if($('.modal form')&&!confirm('Обновить приложение? Несохранённые данные формы будут потеряны.'))return;location.reload();};
 }catch{}finally{checkingUpdate=false;}
}
function registerSW(){
 if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js',{updateViaCache:'none'}).catch(()=>{});
 checkForUpdate();document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')checkForUpdate();});
}

async function boot(){registerSW();await restoreSession();}
let restoringSession=false;
async function restoreSession(){
 if(restoringSession)return;restoringSession=true;
 try{const me=await api('/api/me');app.user=me.user;app.csrf=me.csrf;await refresh();renderShell();}
 catch(err){if(err.message==='AUTH_REQUIRED')renderLogin();else renderConnectionError();}
 finally{restoringSession=false;}
}
function renderConnectionError(){
 $('#app').innerHTML=`<main class="login-panel-wrap"><section class="login-panel"><div class="brandmark">OP</div><h2>Не удалось загрузить приложение</h2><p>Проверьте подключение к интернету и повторите попытку. Повторно вводить пароль пока не нужно.</p><button class="btn btn-primary btn-block" id="retrySession">Повторить</button></section></main>`;
 $('#retrySession').onclick=()=>{const button=$('#retrySession');button.disabled=true;button.textContent='Подключаемся…';restoreSession();};
}


function renderLogin(){closeModal(true);app.user=null;app.csrf=null;app.data={};app.buildingScope='';app.objectReturn=null;issueFilters.state='open';issueFilters.query='';issueFilters.mine=false;$('#app').innerHTML=`<main class="login-shell"><section class="login-hero"><div class="brand"><div class="brandmark">OP</div><div>OWNER PROPERTY</div></div><div class="hero-copy"><div class="eyebrow">● Закрытая система управления</div><h1>Порядок<br>в каждом объекте.</h1><p>Объекты, задания и команда. Всё необходимое для ежедневной работы.</p></div><div class="trust-row"><span class="trust-pill">Без публичной регистрации</span><span class="trust-pill">Ролевой доступ</span><span class="trust-pill">Фотоотчёты</span><span class="trust-pill">PWA</span></div></section><section class="login-panel-wrap"><form class="login-panel" id="loginForm" autocomplete="off"><div class="brandmark">OP</div><h2>Добро пожаловать</h2><p>Используйте учётные данные, выданные владельцем.</p><div class="field"><label>Логин</label><input name="email" required autocomplete="username"></div><div class="field"><label>Пароль</label><input name="password" type="password" required autocomplete="current-password"></div><button class="btn btn-primary btn-block" type="submit">Войти</button><div class="error" id="loginError"></div></form></section></main>`;$('#loginForm').onsubmit=async e=>{e.preventDefault();$('#loginError').textContent='';const fd=new FormData(e.currentTarget);try{const r=await api('/api/login',{method:'POST',body:JSON.stringify({email:fd.get('email'),password:fd.get('password')})});app.user=r.user;app.csrf=r.csrf;app.view='dashboard';await restoreSession();}catch{$('#loginError').textContent='Не удалось войти. Проверьте логин и пароль.';}};}

let refreshGeneration=0;
async function refresh(){const generation=++refreshGeneration,userId=app.user?.id;const req=[api('/api/dashboard'),api('/api/buildings'),api('/api/tenants'),api('/api/issues')];const [dashboard,buildings,tenants,issues]=await Promise.all(req);const data={dashboard,buildings,tenants,issues};const extra=[api('/api/notifications')];const set=['notifications'];
  if(staffMode()&&(hasPerm('issues_edit')||hasPerm('inspections_create'))){extra.push(api('/api/assignees'));set.push('assignees');}
  if(hasPerm('inspections_view')){extra.push(api('/api/inspections'),api('/api/inspection-plans'));set.push('inspections','inspectionPlans');}
  if(hasPerm('equipment_view')){extra.push(api('/api/equipment'));set.push('equipment');}
  if(hasPerm('metrics_view')){extra.push(api('/api/metrics'));set.push('metrics');}
  if(hasPerm('expenses_view')){extra.push(api('/api/expenses'));set.push('expenses');}
  if(hasPerm('security_view')){extra.push(api('/api/security'));set.push('security');}
  if(canManageStaff()){extra.push(api('/api/admin'),api('/api/backup-status'));set.push('admin','backupStatus');}
  if(extra.length){const vals=await Promise.all(extra);vals.forEach((v,i)=>data[set[i]]=v);}
  if(data.admin)data.archivedBuildings=await api('/api/buildings?archived=1');
  if(app.user?.id!==userId||generation!==refreshGeneration)return false;app.data=data;return true;
}

function availableViews(){if(app.user.role==='tenant')return[['dashboard','Главная','⌂'],['issues','Мои обращения','!'],['tenant','Моё помещение','◎'],['settings','Профиль','⚙']];const out=[['dashboard','Сегодня','⌂']];if(hasPerm('buildings_view'))out.push(['buildings','Объекты','▦']);if(hasPerm('inspections_view'))out.push(['inspections','Осмотры','◉']);if(hasPerm('tenants_view'))out.push(['tenants','Арендаторы','◎']);if(hasPerm('issues_view'))out.push(['issues','Задания','✓']);if(hasPerm('equipment_view'))out.push(['equipment','Оборудование','⚙']);if(hasPerm('metrics_view'))out.push(['metrics','Показатели','↗']);if(hasPerm('expenses_view'))out.push(['expenses','Расходы','₽']);if(canManageStaff())out.push(['admin','Сотрудники','♙']);if(hasPerm('security_view'))out.push(['security','Безопасность','◆']);out.push(['settings',canManageStaff()?'Настройки':'Профиль','⚙']);return out;}
function titleForView(){return(availableViews().find(x=>x[0]===app.view)||['','Owner Property'])[1];}
const bellIcon='<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/></svg>';
function navItems(){
 if(app.user.role==='tenant')return availableViews();
 return availableViews().filter(([v])=>['dashboard','buildings','issues','settings'].includes(v));
}
function navigate(view,buildingId=''){
 if(!closeModal())return;app.objectReturn=null;
 app.view=view==='tasks'?'issues':view;app.buildingScope=buildingId;
 renderShell();window.scrollTo(0,0);
}
function renderShell(){
 if(!app.user)return renderLogin();
 if(!availableViews().some(x=>x[0]===app.view))app.view='dashboard';
 if(!app.data.buildings.some(b=>b.id===app.buildingScope))app.buildingScope='';
 const nav=navItems(),unread=(app.data.notifications||[]).filter(n=>!n.readAt).length;
 const active=app.buildingScope?'buildings':nav.some(([v])=>v===app.view)?app.view:'settings';
 const links=mobile=>nav.map(([v,l,ico])=>`<button data-view="${v}" class="${active===v?'active':''}" ${active===v?'aria-current="page"':''}><span class="${mobile?'ico':'nav-icon'}" aria-hidden="true">${ico}</span><span>${l}</span></button>`).join('');
 $('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><div class="brandmark">OP</div><div>Owner Property</div></div><nav class="nav" aria-label="Основные разделы">${links(false)}</nav><div class="sidebar-bottom"><div class="user-card"><div class="user-name">${esc(app.user.name)}</div><div class="user-role">${esc(roleLabel(app.user.role))}</div><div class="app-version">Версия ${APP_VERSION}</div></div><button class="btn btn-ghost" id="logout">Выйти</button></div></aside><main class="main"><header class="topbar"><h1 id="pageTitle">${esc(titleForView())}</h1><div class="top-actions"><button class="icon-btn notify-btn" id="notificationsBtn" aria-label="Уведомления: ${unread} непрочитанных">${bellIcon}${unread?`<span>${unread}</span>`:''}</button><button class="icon-btn" id="refreshBtn" aria-label="Обновить данные">↻</button></div></header><div class="content">${app.buildingScope?`<div class="scope-bar"><button class="link-btn" id="backToBuilding">← ${esc(app.data.buildings.find(b=>b.id===app.buildingScope)?.name)}</button><button class="link-btn" id="clearScope">Все объекты</button></div>`:!nav.some(([v])=>v===app.view)?'<button class="link-btn back-link" id="backToSettings">← Настройки</button>':''}<div id="view"></div></div></main><nav class="mobile-nav" aria-label="Основные разделы">${links(true)}</nav></div>`;
 $$('[data-view]').forEach(b=>b.onclick=()=>navigate(b.dataset.view));
 const logout=async()=>{const userId=app.user.id;try{await api('/api/logout',{method:'POST'});FormSafety.clearForUser(userId);renderLogin();}catch(err){if(err.message!=='AUTH_REQUIRED')toast('Не удалось выйти. Проверьте связь и повторите попытку.');}};
 $('#logout').onclick=logout;
 $('#refreshBtn').onclick=async()=>{checkForUpdate();try{await refresh();renderShell();toast('Данные обновлены');}catch(err){toast(errorText(err));}};
 $('#notificationsBtn').onclick=openNotifications;
 $('#backToBuilding')?.addEventListener('click',()=>openBuilding(app.buildingScope));
 $('#clearScope')?.addEventListener('click',()=>navigate(app.view));
 $('#backToSettings')?.addEventListener('click',()=>navigate('settings'));
 renderView();
 $('#logoutMobile')?.addEventListener('click',logout);
}
function renderView(){
 const v=$('#view'),renderers={dashboard:renderDashboard,buildings:renderBuildings,tenants:renderTenants,tenant:renderTenantSelf,issues:renderIssues,inspections:renderInspections,equipment:renderEquipment,metrics:renderMetrics,expenses:renderExpenses,admin:renderAdmin,security:renderSecurity,settings:renderSettings};
 renderers[app.view]?.(v);
 // Existing module filters remain usable globally; object links open them in context.
 const filter=$({equipment:'#equipmentBuilding',metrics:'#metricBuilding',expenses:'#expenseBuildingFilter'}[app.view]||'#noScopeFilter');
 if(filter&&app.buildingScope){filter.value=app.buildingScope;filter.onchange?.();filter.closest('.field').hidden=true;}
 if(app.view==='admin'){
  const stats=$('.stats',v),backup=$('.backup-summary',v),help=$('.backup-download-help',v),advanced=$('.grid.two',v),workload=$('.workload-grid',v)?.closest('.card');
  foldElements(v,[advanced], 'Распределение заданий и графики осмотров');
  foldElements(v,[stats,workload], 'Нагрузка и статистика');
  foldElements(v,[backup,help], 'Резервные копии');
 }
}
function scopedRows(rows=[]){return app.buildingScope?rows.filter(x=>x.buildingId===app.buildingScope):rows;}
function foldElements(parent,elements,label){
 const nodes=elements.filter(Boolean);if(!nodes.length)return;
 const details=document.createElement('details');details.className='disclosure';
 const summary=document.createElement('summary');summary.textContent=label;details.append(summary);
 parent.append(details);nodes.forEach(node=>details.append(node));return details;
}
function renderSettings(v){
 const sections=availableViews().filter(([key])=>!navItems().some(([v])=>v===key));
 v.innerHTML=`<div class="subhead"><div><h2>${esc(app.user.name)}</h2><p>${esc(roleLabel(app.user.role))} · ${esc(app.user.email||'')}</p></div></div>${canManageStaff()?'<p class="section-intro">Сотрудники, доступы и дополнительные разделы.</p>':'<p class="section-intro">Доступные вам разделы по всем объектам.</p>'}<div class="settings-list">${sections.map(([key,label,icon])=>`<button class="settings-link" data-menu-view="${key}"><span aria-hidden="true">${icon}</span><b>${label}</b><span aria-hidden="true">›</span></button>`).join('')}</div><div class="profile-footer"><span>Owner Property · ${APP_VERSION}</span><button class="btn btn-ghost" id="logoutMobile">Выйти из аккаунта</button></div>`;
 $$('[data-menu-view]',v).forEach(b=>b.onclick=()=>navigate(b.dataset.menuView));
}

function issueTag(i){return`<span class="tag ${i.status==='done'?'done':i.priority==='critical'?'critical':''}">${esc(statusMap[i.status]||i.status)}</span>`;}
function issueCard(i){
 const b=app.data.buildings.find(x=>x.id===i.buildingId),t=app.data.tenants.find(x=>x.id===i.tenantId),overdue=i.due&&i.due<todayLocal()&&!['done','awaiting_acceptance'].includes(i.status);
 return`<button class="issue-card" data-issue="${esc(i.id)}"><div class="issue-main"><div><b>${esc(i.title)}</b><span>${esc(b?.name||'')}${t?' · '+esc(t.company):''}</span></div>${issueTag(i)}</div><div class="issue-meta">${['critical','high'].includes(i.priority)?`<span class="needs-attention">${i.priority==='critical'?'Срочно':'Высокий приоритет'}</span>`:''}<span>${i.responsible?esc(i.responsible):'Нужен исполнитель'}</span>${i.due?`<span class="${overdue?'needs-attention':''}">${overdue?'Просрочено ·':'Срок'} ${fmtDate(i.due)}</span>`:''}</div></button>`;
}

function buildingCard(b){
 const x=buildingSignals(b);
 const alert=x.critical?`${x.critical} критических заданий`:x.overdue?`${x.overdue} просрочено`:x.unassigned?`${x.unassigned} без исполнителя`:x.inspectionOverdue?'Пора провести осмотр':['attention','critical'].includes(b.status)?'Проверьте состояние объекта':'';
 return`<article class="building-card"><button class="building building-main" type="button" data-building="${b.id}"><div><div class="building-top"><b>${esc(b.name)}</b></div><div class="building-address">${esc(b.address||'Адрес не указан')}</div><p class="building-summary ${alert?'needs-attention':''}">${alert|| (x.open?`${x.open} открытых заданий`:'Нет открытых заданий')}</p></div><span class="building-arrow" aria-hidden="true">›</span></button></article>`;
}

function bindBuildingCardActions(){
  $$('[data-building]').forEach(x=>x.onclick=()=>openBuilding(x.dataset.building));
  $$('[data-building-edit]').forEach(x=>x.onclick=e=>{e.stopPropagation();const b=app.data.buildings.find(v=>v.id===x.dataset.buildingEdit);if(b)openBuildingForm(b);});
  $$('[data-building-remove]').forEach(x=>x.onclick=e=>{e.stopPropagation();const b=app.data.buildings.find(v=>v.id===x.dataset.buildingRemove);if(b)removeBuilding(b);});
}
function tenantMini(t,b){if(!t)return'<div class="empty">Нет данных</div>';return`<div class="info-list"><div class="info-item"><div class="k">Объект</div><div class="v">${esc(b?.name||'')}</div></div><div class="info-item"><div class="k">Помещение</div><div class="v">${esc(t.unit||'—')}</div></div><div class="info-item"><div class="k">Площадь</div><div class="v">${num(t.area)} м²</div></div><div class="info-item"><div class="k">Контакт</div><div class="v">${esc(t.contact||'—')}</div></div></div>`;}
function bindIssueLinks(){$$('[data-issue]').forEach(x=>x.onclick=e=>{e.stopPropagation();openIssue(x.dataset.issue);});}

function renderDashboard(v){const d=app.data.dashboard,s=d.stats;if(app.user.role==='tenant'){const t=app.data.tenants[0],b=app.data.buildings[0];v.innerHTML=`<div class="subhead"><div><h2>Добрый день, ${esc(app.user.name)}</h2><p>${esc(b?.name||'')} · помещение ${esc(t?.unit||'')}</p></div><button class="btn btn-primary" id="tenantNewIssue">+ Сообщить о проблеме</button></div><div class="grid stats"><div class="stat"><div class="stat-label">Открытые</div><div class="stat-value">${s.open}</div><div class="stat-foot">ваши обращения</div></div><div class="stat alert"><div class="stat-label">Критические</div><div class="stat-value">${s.critical}</div><div class="stat-foot">требуют внимания</div></div><div class="stat good"><div class="stat-label">Выполнено</div><div class="stat-value">${app.data.issues.filter(i=>i.status==='done').length}</div><div class="stat-foot">за всё время</div></div></div><div class="grid two"><div class="card"><div class="card-head"><h3>Мои обращения</h3></div><div class="card-body"><div class="issue-list">${app.data.issues.slice(0,5).map(issueCard).join('')||'<div class="empty">Обращений нет</div>'}</div></div></div><div class="card"><div class="card-head"><h3>Моё помещение</h3></div><div class="card-body">${tenantMini(t,b)}</div></div></div>`;$('#tenantNewIssue').onclick=()=>openIssueForm();bindIssueLinks();return;}
  const owner=canManageStaff(),open=app.data.issues.filter(i=>i.status!=='done'),mine=open.filter(i=>i.responsibleUserId===app.user.id);
  const urgent=i=>i.priority==='critical'||(i.due&&i.due<=todayLocal()&&i.status!=='awaiting_acceptance')||!i.responsibleUserId;
  const attention=(owner?open.filter(urgent):mine).slice().sort((a,b)=>issueUrgency(b)-issueUrgency(a));
  const plans=(app.data.inspectionPlans||[]).filter(p=>(owner||p.inspectorUserId===app.user.id)&&p.nextDue&&p.nextDue<=todayLocal());
  const equipment=(app.data.equipment||[]).filter(e=>e.nextService&&e.nextService<=todayLocal());
  v.innerHTML=`<div class="home-intro"><p class="eyebrow">${esc(new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'long'}).format(new Date()))}</p><h2>${owner?'Всё важное на сегодня':'Мои задания'}</h2><p>${owner?'Начните с того, что требует решения.':'Откройте задание, выполните работу и отправьте фотоотчёт.'}</p>${hasPerm('issues_edit')?`<button class="btn btn-primary" id="todayNewIssue">${owner?'+ Создать задание':'+ Сообщить о проблеме'}</button>`:''}</div><div class="home-layout"><section class="card"><div class="card-head"><h3>${owner?'Требуют внимания':'Назначено мне'}</h3><span class="tag">${attention.length}</span></div>${owner?`<div class="attention-tabs">${[['all','Все'],['today','Сегодня'],['overdue','Просрочено'],['unassigned','Без исполнителя']].map(([key,label])=>`<button class="btn btn-ghost" data-attention="${key}" aria-pressed="${key==='all'}">${label} · ${(key==='all'?attention:attention.filter(i=>attentionMatches(i,key))).length}</button>`).join('')}</div>`:''}<div class="card-body issue-list" id="attentionResults">${attention.slice(0,6).map(issueCard).join('')||`<div class="empty"><b>${owner?'Срочных заданий нет':'Вам пока не назначены задания'}</b><p>${owner?'Все задания доступны в отдельном разделе.':'Когда появится работа, она будет здесь.'}</p></div>`}</div><div class="card-foot"><button class="link-btn" id="allTasks">${owner?'Все задания':attention.length>6?'Показать все мои задания':'Открыть задания'} →</button></div></section><aside class="home-aside">${plans.length?`<section class="card"><div class="card-head"><h3>Пора провести осмотр</h3></div><div class="card-body shortcut-list">${plans.map(p=>`<button class="settings-link" data-today-inspection="${p.buildingId}"><b>${esc(app.data.buildings.find(b=>b.id===p.buildingId)?.name||'Объект')}</b><span>${fmtDate(p.nextDue)}</span></button>`).join('')}</div></section>`:''}${equipment.length?`<button class="settings-link maintenance-shortcut" id="todayEquipment"><b>Обслуживание оборудования</b><span>${equipment.length} →</span></button>`:''}${hasPerm('buildings_view')?`<button class="settings-link" id="todayBuildings"><b>Объекты</b><span>${app.data.buildings.length} →</span></button>`:''}${owner&&app.data.backupStatus?.stale?'<button class="settings-link needs-attention" id="todayBackup"><b>Проверить резервную копию</b><span>→</span></button>':''}</aside></div>`;
  $$('[data-attention]').forEach(b=>b.onclick=()=>{const rows=attention.filter(i=>attentionMatches(i,b.dataset.attention));$('#attentionResults').innerHTML=rows.slice(0,6).map(issueCard).join('')||'<div class="empty">В этой группе заданий нет</div>';$$('[data-attention]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));bindIssueLinks();});
  $('#todayNewIssue')?.addEventListener('click',()=>openIssueForm());
  $('#allTasks').onclick=()=>{issueFilters.state='open';issueFilters.query='';issueFilters.mine=!owner;navigate('issues');};
  $('#todayBuildings')?.addEventListener('click',()=>navigate('buildings'));
  $('#todayEquipment')?.addEventListener('click',()=>{navigate('equipment');$('#equipmentState').value='due';$('#equipmentState').onchange();});
  $('#todayBackup')?.addEventListener('click',()=>{navigate('admin');const d=$('#downloadBackup')?.closest('details')||$$('details').find(d=>d.textContent.includes('Резервные копии'));if(d)d.open=true;d?.scrollIntoView({block:'center'});});
  $$('[data-today-inspection]').forEach(b=>b.onclick=()=>hasPerm('inspections_create')?openInspectionForm(b.dataset.todayInspection):navigate('inspections',b.dataset.todayInspection));bindIssueLinks();
}

const buildingFilters={query:'',state:'all',sort:'attention'};
function buildingSignals(b){
 const local=new Date();local.setMinutes(local.getMinutes()-local.getTimezoneOffset());const today=local.toISOString().slice(0,10);
 const open=app.data.issues.filter(i=>i.buildingId===b.id&&i.status!=='done');
 const plan=(app.data.inspectionPlans||[]).find(p=>p.buildingId===b.id&&p.active!==false);
 return {open:open.length,critical:open.filter(i=>i.priority==='critical').length,overdue:open.filter(i=>i.status==='overdue'||(i.due&&i.due<today)).length,unassigned:open.filter(i=>!i.responsibleUserId).length,inspectionOverdue:!!(plan?.nextDue&&plan.nextDue<today)};
}
function filteredBuildings(){
 const q=buildingFilters.query.trim().toLocaleLowerCase('ru-RU');
 const rows=app.data.buildings.map(b=>({b,signals:buildingSignals(b)})).filter(({b,signals:x})=>{
  if(q&&![b.name,b.address,b.manager].some(v=>String(v||'').toLocaleLowerCase('ru-RU').includes(q)))return false;
  return buildingFilters.state==='all'||(buildingFilters.state==='attention'&&(x.open||x.inspectionOverdue||['attention','critical'].includes(b.status)))||(buildingFilters.state==='overdue'&&(x.overdue||x.inspectionOverdue))||(buildingFilters.state==='unassigned'&&x.unassigned);
 });
 const urgency=({b,signals:x})=>(x.critical+(b.status==='critical'?1:0))*10000+(x.overdue+Number(x.inspectionOverdue))*100+x.unassigned*10+x.open+(b.status==='attention'?1:0);
 return rows.sort((a,b)=>(buildingFilters.sort==='name'?0:buildingFilters.sort==='occupancy'?((a.b.area?a.b.occupied/a.b.area:0)-(b.b.area?b.b.occupied/b.b.area:0)):urgency(b)-urgency(a))||a.b.name.localeCompare(b.b.name,'ru')).map(x=>x.b);
}
function renderBuildings(v){
 const archived=app.data.archivedBuildings||[];
 v.innerHTML=`<div class="subhead"><div><h2>Объекты</h2><p>Откройте объект — всё нужное уже внутри.</p></div><div class="action-row">${app.user.role==='owner'?'<button class="btn btn-primary" id="addBuilding">+ Добавить объект</button>':''}${hasPerm('inspections_create')?'<button class="btn btn-secondary" id="buildingInspection">+ Новый осмотр</button>':''}</div></div>
 <div class="building-toolbar"><div class="field"><label for="buildingSearch">Найти объект</label><input id="buildingSearch" type="search" placeholder="Название, адрес, ответственный" value="${esc(buildingFilters.query)}"></div><div class="field"><label for="buildingState">Показать</label><select id="buildingState">${[['all','Все объекты'],['attention','Требуют внимания'],['overdue','Есть просрочки'],['unassigned','Задачи без исполнителя']].map(([k,v])=>`<option value="${k}" ${buildingFilters.state===k?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label for="buildingSort">Порядок</label><select id="buildingSort">${[['attention','Сначала срочные'],['name','По названию'],['occupancy','Сначала свободные площади']].map(([k,v])=>`<option value="${k}" ${buildingFilters.sort===k?'selected':''}>${v}</option>`).join('')}</select></div></div>
 <div class="card"><div class="card-head"><h3>Активные объекты</h3><span class="tag" id="buildingCount" role="status"></span></div><div class="card-body"><div class="building-list" id="buildingResults"></div></div></div>${app.user.role==='owner'?`<details class="card archive-card mt-16"><summary class="card-head">Архив · ${archived.length}</summary><div class="card-body"><div class="building-list">${archived.map(archivedBuildingCard).join('')||'<div class="empty">Архив пуст</div>'}</div></div></details>`:''}`;
 const update=()=>{const rows=filteredBuildings();$('#buildingCount').textContent=`${rows.length} из ${app.data.buildings.length}`;$('#buildingResults').innerHTML=rows.map(buildingCard).join('')||`<div class="empty">${app.data.buildings.length?'Ничего не найдено. Измените поиск или фильтр.':'Объектов пока нет.'}</div>`;bindBuildingCardActions();};
 $('#buildingSearch').oninput=e=>{buildingFilters.query=e.target.value;update();};$('#buildingState').onchange=e=>{buildingFilters.state=e.target.value;update();};$('#buildingSort').onchange=e=>{buildingFilters.sort=e.target.value;update();};update();
 foldElements($('.building-toolbar'),[$('#buildingState').closest('.field'),$('#buildingSort').closest('.field'),$('#buildingInspection')],'Фильтры и осмотры');
 $('#addBuilding')?.addEventListener('click',()=>openBuildingForm());$('#buildingInspection')?.addEventListener('click',()=>openInspectionForm());
 $$('[data-archived-building]').forEach(x=>x.onclick=()=>openArchivedBuilding(x.dataset.archivedBuilding));
 $$('[data-building-restore]').forEach(x=>x.onclick=e=>{e.stopPropagation();restoreBuilding(x.dataset.buildingRestore);});
 $$('[data-building-delete]').forEach(x=>x.onclick=e=>{e.stopPropagation();deleteArchivedBuilding(x.dataset.buildingDelete);});
}

function openBuilding(id){
 const b=app.data.buildings.find(x=>x.id===id);if(!b)return;
 const issues=app.data.issues.filter(i=>i.buildingId===id),open=issues.filter(i=>i.status!=='done').sort((a,b)=>issueUrgency(b)-issueUrgency(a));
 const sections=availableViews().filter(([key])=>['tenants','equipment','metrics','expenses','inspections'].includes(key));
 modal(`<div class="modal-head"><div><h3>${esc(b.name)}</h3><div class="building-address">${esc(b.address)}</div></div><button class="icon-btn" data-close aria-label="Закрыть">×</button></div><div class="modal-body"><div class="object-facts"><span>${num(b.area)} м²</span><span>${app.data.tenants.filter(t=>t.buildingId===id).length} арендаторов</span><span>${open.length} открытых заданий</span></div><nav class="object-sections" aria-label="Разделы объекта">${sections.map(([key,label])=>`<button class="btn btn-secondary" data-object-view="${key}">${label} →</button>`).join('')}</nav><div class="section-title"><h3>Задания объекта</h3></div><div class="issue-list">${open.map(issueCard).join('')||'<div class="empty">Открытых заданий нет</div>'}</div>${issues.some(i=>i.status==='done')?`<details class="disclosure"><summary>Выполненные задания · ${issues.filter(i=>i.status==='done').length}</summary><div class="issue-list">${issues.filter(i=>i.status==='done').map(issueCard).join('')}</div></details>`:''}<details class="disclosure"><summary>Сведения об объекте${canManageStaff()?' и управление':''}</summary><dl class="expense-lines"><div><dt>Ответственный</dt><dd>${esc(b.manager||'Не указан')}</dd></div><div><dt>Занято</dt><dd>${num(b.occupied)} м²</dd></div><div><dt>Этажей</dt><dd>${num(b.floors)}</dd></div><div><dt>Мощность</dt><dd>${num(b.powerKw)} кВт</dd></div><div><dt>Состояние</dt><dd>${esc(inspectionStatusMap[b.status]||b.status)}</dd></div></dl>${b.note?`<p class="building-note">${esc(b.note)}</p>`:''}${canManageStaff()?'<div class="row-actions"><button class="btn btn-secondary" id="editBuilding">Редактировать объект</button><button class="btn btn-ghost danger-link" id="archiveBuilding">В архив</button></div>':''}</details></div><div class="modal-actions">${hasPerm('inspections_create')?'<button class="btn btn-secondary" id="inspectBuilding">Провести осмотр</button>':''}${hasPerm('issues_edit')?'<button class="btn btn-primary" id="buildingTask">+ Создать задание</button>':'<button class="btn btn-ghost" data-close>Закрыть</button>'}</div>`,true);
 $$('[data-close]').forEach(x=>x.onclick=closeModal);
 $('#buildingTask')?.addEventListener('click',()=>openIssueForm('',id));
 $('#editBuilding')?.addEventListener('click',()=>openBuildingForm(b));
 $('#archiveBuilding')?.addEventListener('click',()=>archiveBuilding(b));
 $('#inspectBuilding')?.addEventListener('click',()=>openInspectionForm(id));
 $$('[data-object-view]').forEach(x=>x.onclick=()=>navigate(x.dataset.objectView,id));bindIssueLinks();$('#modal').dataset.buildingId=id;app.objectReturn=null;
}

function archivedBuildingCard(b){return`<article class="building-card archived"><button class="building building-main" type="button" data-archived-building="${b.id}"><div><div class="building-top"><span class="status-dot"></span><b>${esc(b.name)}</b></div><div class="building-address">${esc(b.address)}</div><div class="chips"><span>в архиве с ${fmtDate(b.archivedAt)}</span></div></div><div class="metric-mini"><strong>Архив</strong><span>история сохранена</span></div></button><div class="building-actions"><button class="btn btn-secondary btn-compact" type="button" data-building-restore="${b.id}">Восстановить</button><button class="btn btn-danger btn-compact" type="button" data-building-delete="${b.id}">Удалить навсегда</button></div></article>`;}
function openBuildingForm(b=null){nextDraftKey='building:'+(b?.id||'new');modal(`<form id="buildingForm"><div class="modal-head"><div><h3>${b?'Редактировать объект':'Добавить объект'}</h3><div class="building-address">Рабочие характеристики объекта — без договоров и документов</div></div><button class="icon-btn" type="button" data-close>×</button></div><div class="modal-body"><div class="form-grid"><div class="field span2"><label>Название объекта</label><input name="name" value="${esc(b?.name||'')}" required maxlength="120"></div><div class="field span2"><label>Адрес</label><input name="address" value="${esc(b?.address||'')}" maxlength="220"></div><div class="field"><label>Площадь, м²</label><input name="area" type="number" min="0" value="${Number(b?.area||0)}"></div><div class="field"><label>Занято, м²</label><input name="occupied" type="number" min="0" value="${Number(b?.occupied||0)}"></div><div class="field"><label>Этажей</label><input name="floors" type="number" min="0" value="${Number(b?.floors||0)}"></div><div class="field"><label>Мощность, кВт</label><input name="powerKw" type="number" min="0" value="${Number(b?.powerKw||0)}"></div><div class="field"><label>Состояние</label><select name="status"><option value="ok" ${b?.status==='ok'?'selected':''}>Норма</option><option value="attention" ${b?.status==='attention'?'selected':''}>Внимание</option><option value="critical" ${b?.status==='critical'?'selected':''}>Критично</option></select></div><div class="field"><label>Ответственный</label><input name="manager" value="${esc(b?.manager||'')}"></div><div class="field span2"><label>Рабочее примечание</label><textarea name="note">${esc(b?.note||'')}</textarea></div></div></div><div class="modal-actions"><button class="btn btn-ghost" type="button" data-close>Отмена</button><button class="btn btn-primary" type="submit">${b?'Сохранить':'Создать объект'}</button></div></form>`);$$('[data-close]').forEach(x=>x.onclick=closeModal);$('#buildingForm').onsubmit=async e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.currentTarget));try{await api(b?'/api/buildings/'+encodeURIComponent(b.id):'/api/buildings',{method:b?'PATCH':'POST',body:JSON.stringify(o)});await refresh();closeModal();renderShell();toast(b?'Объект обновлён':'Объект создан');}catch(err){toast(errorText(err));}};}
async function archiveBuilding(b){if(!confirm(`Переместить объект «${b.name}» в архив? История и связанные данные сохранятся.`))return;try{await api('/api/buildings/'+encodeURIComponent(b.id)+'/archive',{method:'POST',body:'{}'});await refresh();closeModal();renderShell();toast('Объект перемещён в архив');}catch(err){toast(errorText(err));}}
async function removeBuilding(b){if(!confirm(`Удалить объект «${b.name}» из активных? Он будет перемещён в архив, история сохранится. Окончательно удалить пустой объект можно из архива.`))return;try{await api('/api/buildings/'+encodeURIComponent(b.id)+'/archive',{method:'POST',body:'{}'});await refresh();closeModal();renderShell();toast('Объект перемещён в архив');}catch(err){toast(errorText(err));}}
async function restoreBuilding(id){try{await api('/api/buildings/'+encodeURIComponent(id)+'/restore',{method:'POST',body:'{}'});await refresh();closeModal();renderShell();toast('Объект восстановлен');}catch(err){toast(errorText(err));}}
async function deleteArchivedBuilding(id){const b=(app.data.archivedBuildings||[]).find(x=>x.id===id);const confirmText=prompt(`Для безвозвратного удаления пустого объекта «${b?.name||''}» введите УДАЛИТЬ`);if(confirmText!=='УДАЛИТЬ')return;try{await api('/api/buildings/'+encodeURIComponent(id),{method:'DELETE'});await refresh();closeModal();renderShell();toast('Объект удалён');}catch(err){toast(errorText(err));}}

function openArchivedBuilding(id){const b=(app.data.archivedBuildings||[]).find(x=>x.id===id);if(!b)return;modal(`<div class="modal-head"><div><h3>${esc(b.name)}</h3><div class="building-address">Архивный объект · ${esc(b.address)}</div></div><button class="icon-btn" data-close>×</button></div><div class="modal-body"><div class="warning">Архивирование не удаляет эксплуатационную историю. Безвозвратное удаление разрешено только для объекта без связанных записей.</div><div class="info-list mt-16"><div class="info-item"><div class="k">Площадь</div><div class="v">${num(b.area)} м²</div></div><div class="info-item"><div class="k">Дата архивации</div><div class="v">${fmtDateTime(b.archivedAt)}</div></div></div></div><div class="modal-actions"><button class="btn btn-primary" id="restoreBuilding">Восстановить</button><button class="btn btn-danger" id="deleteBuilding">Удалить навсегда</button><button class="btn btn-ghost" data-close>Закрыть</button></div>`);$$('[data-close]').forEach(x=>x.onclick=closeModal);$('#restoreBuilding').onclick=()=>restoreBuilding(id);$('#deleteBuilding').onclick=()=>deleteArchivedBuilding(id);}

function renderTenants(v){if(app.user.role==='tenant')return renderTenantSelf(v);v.innerHTML=`<div class="subhead"><div><h2>Арендаторы</h2><p>Помещения и эксплуатационные обращения — без договоров</p></div>${hasPerm('tenants_manage')?'<button class="btn btn-primary" id="newTenant">+ Добавить</button>':''}</div><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Арендатор</th><th>Объект</th><th>Помещение</th><th>Площадь</th><th>Проблем</th><th></th></tr></thead><tbody>${scopedRows(app.data.tenants).map(t=>{const b=app.data.buildings.find(x=>x.id===t.buildingId),n=app.data.issues.filter(i=>i.tenantId===t.id&&i.status!=='done').length;return`<tr><td><b>${esc(t.company)}</b><div class="muted">${esc(t.contact||'')}</div></td><td>${esc(b?.name||'')}</td><td>${esc(t.unit||'—')}</td><td>${num(t.area)} м²</td><td>${n}</td><td><button class="link-btn" data-tenant="${t.id}">Открыть</button></td></tr>`;}).join('')}</tbody></table></div></div>`;$('#newTenant')?.addEventListener('click',()=>openTenantForm());$$('[data-tenant]').forEach(x=>x.onclick=()=>openTenant(x.dataset.tenant));}
function renderTenantSelf(v){const t=app.data.tenants[0],b=app.data.buildings[0];if(!t)return v.innerHTML='<div class="empty">Помещение не назначено</div>';v.innerHTML=`<div class="subhead"><div><h2>Моё помещение</h2><p>Только эксплуатационная информация</p></div></div><div class="hero-tenant"><div><h3>${esc(t.company)}</h3><p>${esc(b?.name||'')} · ${esc(t.unit)}</p></div><div><div class="big-area">${num(t.area)} м²</div></div></div><div class="card mt-16"><div class="card-head"><h3>Сведения</h3></div><div class="card-body">${tenantMini(t,b)}<div class="warning mt-16">В системе не хранятся договоры, банковские документы или иные конфиденциальные вложения.</div></div></div>`;}
function openTenant(id){const t=app.data.tenants.find(x=>x.id===id),b=app.data.buildings.find(x=>x.id===t?.buildingId);if(!t)return;const issues=app.data.issues.filter(i=>i.tenantId===id);const checks=(app.data.inspections||[]).flatMap(i=>(i.tenantChecks||[]).filter(c=>c.tenantId===id).map(c=>({...c,inspection:i}))).slice(0,5);modal(`<div class="modal-head"><div><h3>${esc(t.company)}</h3><div class="building-address">${esc(b?.name||'')} · ${esc(t.unit)}</div></div><button class="icon-btn" data-close>×</button></div><div class="modal-body">${tenantMini(t,b)}<div class="section-title"><div><h3>Проблемы арендатора</h3></div></div><div class="issue-list">${issues.map(issueCard).join('')||'<div class="empty">Проблем нет</div>'}</div>${checks.length?`<div class="section-title"><div><h3>Последние проверки при обходах</h3></div></div><div class="inspection-mini-list">${checks.map(c=>`<button class="inspection-mini" data-inspection="${c.inspection.id}"><b>${fmtDateTime(c.inspection.occurredAt)} · ${c.status==='ok'?'Норма':c.status==='problem'?'Есть проблема':'Не осмотрен'}</b><span>${esc(c.notes||'Без замечаний')}</span></button>`).join('')}</div>`:''}</div><div class="modal-actions">${hasPerm('issues_edit')?`<button class="btn btn-primary" id="tenantIssue">+ Проблема</button>`:''}${hasPerm('tenants_manage')?'<button class="btn btn-secondary" id="editTenant">Редактировать</button>':''}<button class="btn btn-ghost" data-close>Закрыть</button></div>`,true);$('#editTenant')?.addEventListener('click',()=>openTenantForm(t.id));$$('[data-close]').forEach(x=>x.onclick=closeModal);$('#tenantIssue')?.addEventListener('click',()=>{closeModal();openIssueForm(t.id,t.buildingId);});$$('[data-inspection]').forEach(x=>x.onclick=()=>{closeModal();openInspection(x.dataset.inspection);});bindIssueLinks();}

const issueFilters={state:'open',query:'',mine:false};
function attentionMatches(i,key){return key==='all'||(key==='today'&&i.due===todayLocal()&&i.status!=='awaiting_acceptance')||(key==='overdue'&&i.due&&i.due<todayLocal()&&i.status!=='awaiting_acceptance')||(key==='unassigned'&&!i.responsibleUserId);}
function issueUrgency(i){return (i.priority==='critical'?10000:0)+(i.due&&i.due<todayLocal()?1000:0)+(!i.responsibleUserId?100:0)+(i.priority==='high'?10:0);}
function renderIssues(v){
 const tenant=app.user.role==='tenant';
 v.innerHTML=`<div class="subhead"><div><h2>${tenant?'Мои обращения':'Задания'}</h2><p>От обращения до результата — в одном списке.</p></div>${hasPerm('issues_edit')||tenant?`<button class="btn btn-primary" id="newIssue">${tenant?'+ Сообщить о проблеме':'+ Создать задание'}</button>`:''}</div><div class="task-toolbar"><div class="segmented" aria-label="Статус заданий">${[['open','Открытые'],['done','Выполненные'],['all','Все']].map(([key,label])=>`<button data-task-state="${key}" aria-pressed="${key===issueFilters.state}">${label}</button>`).join('')}</div>${!tenant?`<label class="mine-toggle"><input type="checkbox" id="onlyMine" ${issueFilters.mine?'checked':''}> Назначенные мне</label>`:''}</div><div class="field"><label for="taskSearch">Найти задание</label><input type="search" id="taskSearch" value="${esc(issueFilters.query)}" placeholder="Задание, объект или исполнитель"></div><div id="taskResults" class="issue-list"></div>`;
 const render=()=>{const query=issueFilters.query.trim().toLocaleLowerCase('ru-RU'),rows=scopedRows(app.data.issues).filter(i=>(issueFilters.state==='all'||(issueFilters.state==='done'?i.status==='done':i.status!=='done'))&&(!issueFilters.mine||tenant||i.responsibleUserId===app.user.id)&&(!query||[i.title,i.responsible,app.data.buildings.find(b=>b.id===i.buildingId)?.name].join(' ').toLocaleLowerCase('ru-RU').includes(query))).slice().sort((a,b)=>issueUrgency(b)-issueUrgency(a));$('#taskResults').innerHTML=rows.map(issueCard).join('')||'<div class="empty">Нет заданий по выбранным условиям.</div>';bindIssueLinks();};
 $$('[data-task-state]').forEach(b=>b.onclick=()=>{issueFilters.state=b.dataset.taskState;$$('[data-task-state]').forEach(x=>x.setAttribute('aria-pressed',x===b?'true':'false'));render();});
 $('#taskSearch').oninput=e=>{issueFilters.query=e.target.value;render();};$('#onlyMine')?.addEventListener('change',e=>{issueFilters.mine=e.target.checked;render();});
 $('#newIssue')?.addEventListener('click',()=>openIssueForm('',app.buildingScope||''));render();
}

function reportCard(r){return`<div class="work-report ${r.kind==='solution'?'solution':''}"><div class="report-head"><div><b>${r.kind==='solution'?'Итоговый отчёт':'Фотоотчёт по работе'}</b><div class="building-address">${fmtDateTime(r.at)}</div></div>${r.kind==='solution'?'<span class="tag done">Решено</span>':'<span class="tag">Работа</span>'}</div><div class="report-signature"><span>Исполнитель / подпись</span><strong>✓ ${esc(r.author||'Не указан')}</strong></div><div class="report-text">${esc(r.text)}</div>${(r.photos||[]).length?photoGrid(r.photos):''}${r.recordedBy?`<div class="report-recorded">Зафиксировал в системе: ${esc(r.recordedBy)}</div>`:''}</div>`;}
function tenantAcceptancePanel(i){const h=i.acceptanceHistory||[],latest=h[h.length-1];if(i.status==='awaiting_acceptance'){return app.user.role==='tenant'?`<div class="tenant-acceptance waiting"><div><span>ТРЕБУЕТСЯ ВАШЕ ПОДТВЕРЖДЕНИЕ</span><strong>Исполнитель сообщил, что проблема устранена</strong><p>Проверьте результат и подтвердите либо верните в работу.</p></div><div class="accept-actions"><button class="btn btn-primary" id="tenantAccept">✓ Проблема устранена</button><button class="btn btn-danger" id="tenantReject">Проблема осталась</button></div></div>`:`<div class="tenant-acceptance waiting"><div><span>ОЖИДАЕТ ПОДТВЕРЖДЕНИЯ АРЕНДАТОРА</span><strong>Фотоотчёт отправлен на проверку</strong></div></div>`;}if(i.status==='done'&&i.tenantAcceptedAt)return`<div class="tenant-acceptance accepted"><div><span>ПРИНЯТО АРЕНДАТОРОМ</span><strong>✓ ${esc(i.tenantAcceptedBy||'Арендатор')}</strong><p>${fmtDateTime(i.tenantAcceptedAt)}</p></div></div>`;if(latest?.decision==='rejected')return`<div class="tenant-acceptance rejected"><div><span>РЕЗУЛЬТАТ НЕ ПРИНЯТ</span><strong>Проблема возвращена в работу</strong><p>${fmtDateTime(latest.at)} · ${esc(latest.comment||'')}</p></div>${latest.photos?.length?photoGrid(latest.photos):''}</div>`;return'';}
function issueEvidenceComparison(i){const before=(i.photos||[]).filter(p=>p.kind==='problem')[0],solution=(i.reports||[]).filter(r=>r.kind==='solution').slice(-1)[0],after=solution?.photos?.slice(-1)[0];const pane=(label,p,cls)=>p?`<a class="compare-pane ${cls}" href="${esc(p.url)}" target="_blank"><div class="compare-label">${label}</div><img src="${esc(p.url)}" alt="${label}"><div class="compare-meta"><b>${fmtDateTime(p.at)}</b><span>${esc(p.actor||'')}</span></div></a>`:`<div class="compare-pane ${cls} empty"><div class="compare-label">${label}</div><div class="compare-placeholder"><strong>Фото пока нет</strong></div></div>`;return`<div class="evidence-compare">${pane('ДО',before,'before')}<div class="compare-arrow">→</div>${pane('ПОСЛЕ',after,'after')}</div>${solution?`<div class="solution-signoff"><div><span>${i.status==='awaiting_acceptance'?'ОЖИДАЕТ ПОДТВЕРЖДЕНИЯ':'РЕШЕНИЕ'}</span><strong>✓ ${esc(solution.author)}</strong></div><div><b>${fmtDateTime(solution.at)}</b><small>подпись и время</small></div></div>`:''}`;}
function openIssue(id){const i=app.data.issues.find(x=>x.id===id);if(!i)return;const b=app.data.buildings.find(x=>x.id===i.buildingId),t=app.data.tenants.find(x=>x.id===i.tenantId),problemPhotos=(i.photos||[]).filter(p=>p.kind==='problem');modal(`<div class="modal-head"><div><h3>${esc(i.title)}</h3><div class="building-address">${esc(b?.name||'')}${t?' · '+esc(t.company):''}${i.sourceInspectionId?' · выявлено при осмотре':''}</div></div><button class="icon-btn" data-close>×</button></div><div class="modal-body">${(i.reports||[]).some(r=>r.kind==='solution')?issueEvidenceComparison(i):''}${tenantAcceptancePanel(i)}<div class="info-list mt-16"><div class="info-item"><div class="k">Статус</div><div class="v">${esc(statusMap[i.status]||i.status)}</div></div><div class="info-item"><div class="k">Приоритет</div><div class="v">${esc(priorityMap[i.priority]||i.priority)}</div></div><div class="info-item"><div class="k">Ответственный</div><div class="v">${esc(i.responsible||'Не назначен')}</div></div><div class="info-item"><div class="k">Срок</div><div class="v">${fmtDate(i.due)}</div></div></div><div class="section-title"><div><h3>Фото проблемы</h3><p>Исходное состояние с датой и автором</p></div>${(app.user.role==='tenant'||hasPerm('issues_edit'))?'<button class="btn btn-secondary" id="addProblemPhotos">+ Фото</button>':''}</div>${photoGrid(problemPhotos)}<div class="section-title"><div><h3>Отчёты по решению</h3></div>${hasPerm('issues_edit')?'<button class="btn btn-secondary" id="addReport">+ Отчёт</button>':''}</div><div class="reports-list">${(i.reports||[]).map(reportCard).join('')||'<div class="photo-empty">Отчётов пока нет</div>'}</div><details class="disclosure"><summary>История задания</summary><div class="log">${(i.timeline||[]).slice().reverse().map(x=>`<div class="log-row"><div class="time">${fmtDateTime(x.at)}</div><div><b>${esc(x.actor||'Система')}</b></div><div>${esc(x.text)}</div></div>`).join('')}</div></details></div><div class="modal-actions">${hasPerm('issues_edit')?`<button class="btn btn-ghost" id="editIssue">Изменить</button>${!['done','awaiting_acceptance','in_progress'].includes(i.status)?'<button class="btn btn-secondary" id="startIssue">Начать работу</button>':''}${!['done','awaiting_acceptance'].includes(i.status)?'<button class="btn btn-primary" id="quickSolve">Отправить фотоотчёт</button>':''}`:''}<button class="btn btn-ghost" data-close>Закрыть</button></div>`,true);$$('[data-close]').forEach(x=>x.onclick=closeModal);$('#addProblemPhotos')?.addEventListener('click',()=>{closeModal();openIssuePhotoForm(i);});$('#addReport')?.addEventListener('click',()=>{closeModal();openReportForm(i,false);});$('#startIssue')?.addEventListener('click',async e=>{e.currentTarget.disabled=true;try{await api('/api/issues/'+encodeURIComponent(i.id),{method:'PATCH',body:JSON.stringify({status:'in_progress'})});await refresh();renderShell();openIssue(i.id);toast('Задание в работе');}catch(err){toast(errorText(err));const b=$('#startIssue');if(b)b.disabled=false;}});$('#quickSolve')?.addEventListener('click',()=>{closeModal();openReportForm(i,true);});$('#editIssue')?.addEventListener('click',()=>{closeModal();openIssueEdit(i);});$('#tenantAccept')?.addEventListener('click',()=>{closeModal();openTenantDecisionForm(i,'accepted');});$('#tenantReject')?.addEventListener('click',()=>{closeModal();openTenantDecisionForm(i,'rejected');});}

function inspectionDueClass(p){if(!p?.nextDue)return'';const d=new Date(p.nextDue+'T23:59:59'),now=new Date();if(d<now)return'overdue';if((d-now)/864e5<=7)return'due';return'ok';}
function renderInspections(v){const plans=scopedRows(app.data.inspectionPlans),inspections=scopedRows(app.data.inspections);v.innerHTML=`<div class="subhead"><div><h2>Осмотры объектов</h2><p>Регламентный обход с фото 3–4 сторон здания и проверкой арендаторов</p></div>${hasPerm('inspections_create')?'<button class="btn btn-primary" id="newInspection">+ Провести осмотр</button>':''}</div><div class="grid inspection-plans">${plans.map(p=>{const b=app.data.buildings.find(x=>x.id===p.buildingId),cls=inspectionDueClass(p),ins=(app.data.assignees||app.data.admin?.users||[]).find(x=>x.id===p.inspectorUserId);return`<div class="inspection-plan ${cls}"><div><span>${cls==='overdue'?'ПРОСРОЧЕНО':cls==='due'?'НА ЭТОЙ НЕДЕЛЕ':'ПО ПЛАНУ'}</span><h3>${esc(b?.name||p.buildingId)}</h3><p>Периодичность: каждые ${p.frequencyDays} дней</p></div><div class="inspection-plan-date"><strong>${fmtDate(p.nextDue)}</strong><small>${esc(p.inspectorName||ins?.name||'Инспектор не назначен')}</small></div></div>`;}).join('')}</div><div class="card"><div class="card-head"><h3>История осмотров</h3><span class="tag">${inspections.length}</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Дата</th><th>Объект</th><th>Инспектор</th><th>Состояние</th><th>Арендаторы</th><th>Создано проблем</th><th></th></tr></thead><tbody>${inspections.map(i=>{const b=app.data.buildings.find(x=>x.id===i.buildingId);return`<tr><td>${fmtDateTime(i.occurredAt)}</td><td><b>${esc(b?.name||'')}</b></td><td>${esc(i.inspectorName)}</td><td>${esc(inspectionStatusMap[i.overallCondition]||i.overallCondition)}</td><td>${i.tenantChecks?.length||0}</td><td>${i.createdIssueIds?.length||0}</td><td><button class="link-btn" data-inspection="${i.id}">Отчёт</button></td></tr>`;}).join('')||'<tr><td colspan="7"><div class="empty">Осмотров пока нет</div></td></tr>'}</tbody></table></div></div>`;$('#newInspection')?.addEventListener('click',()=>openInspectionForm(app.buildingScope||''));$$('[data-inspection]').forEach(x=>x.onclick=()=>openInspection(x.dataset.inspection));}
function openInspection(id){const i=(app.data.inspections||[]).find(x=>x.id===id);if(!i)return;const b=app.data.buildings.find(x=>x.id===i.buildingId);modal(`<div class="modal-head"><div><h3>Осмотр · ${esc(b?.name||'')}</h3><div class="building-address">${fmtDateTime(i.occurredAt)} · ${esc(i.inspectorName)}</div></div><button class="icon-btn" data-close>×</button></div><div class="modal-body"><div class="inspection-sign"><span>ПОДПИСЬ ИНСПЕКТОРА</span><strong>✓ ${esc(i.signature||i.inspectorName)}</strong><small>${fmtDateTime(i.createdAt)}</small></div><div class="section-title"><div><h3>Вид объекта снаружи</h3><p>Фото 3–4 сторон здания</p></div></div>${photoGrid(i.exteriorPhotos||[],true)}<div class="section-title"><div><h3>Общее состояние</h3></div></div><div class="info-list"><div class="info-item"><div class="k">Оценка</div><div class="v">${esc(inspectionStatusMap[i.overallCondition]||i.overallCondition)}</div></div><div class="info-item"><div class="k">Комментарий</div><div class="v">${esc(i.notes||'Без замечаний')}</div></div></div>${i.buildingFinding?`<div class="inspection-finding critical"><div><span>ПРОБЛЕМА ОБЪЕКТА</span><strong>${esc(i.buildingFinding.title)}</strong><p>${esc(i.buildingFinding.notes||'')}</p></div>${photoGrid(i.buildingFinding.photos||[])}${i.buildingFinding.issueId?`<button class="btn btn-secondary" data-issue="${i.buildingFinding.issueId}">Открыть созданную проблему</button>`:''}</div>`:''}<div class="section-title"><div><h3>Осмотр арендаторов</h3></div></div><div class="tenant-check-list">${(i.tenantChecks||[]).map(c=>{const t=app.data.tenants.find(x=>x.id===c.tenantId);return`<div class="tenant-check ${c.status}"><div class="tenant-check-head"><div><b>${esc(t?.company||c.tenantId)}</b><span>${esc(t?.unit||'')}</span></div><strong>${c.status==='ok'?'✓ Норма':c.status==='problem'?'! Проблема':'— Не осмотрен'}</strong></div>${c.notes?`<p>${esc(c.notes)}</p>`:''}${c.photos?.length?photoGrid(c.photos):''}${c.issueId?`<button class="btn btn-secondary" data-issue="${c.issueId}">Открыть проблему</button>`:''}</div>`;}).join('')||'<div class="empty">Арендаторы не проверялись</div>'}</div></div>${(i.photoHistory||[]).length?`<details class="disclosure"><summary>Изменения фотографий</summary>${i.photoHistory.map(h=>`<p>${fmtDateTime(h.at)} · ${esc(h.actor)} · ${esc(h.text)}</p>`).join('')}</details>`:''}<div class="modal-actions"><button class="btn btn-ghost" data-close>Закрыть</button></div>`,true);$$('[data-close]').forEach(x=>x.onclick=closeModal);bindIssueLinks();}
function tenantCheckRows(buildingId){const ts=app.data.tenants.filter(t=>t.buildingId===buildingId);return ts.map(t=>`<div class="inspection-tenant-row" data-check-tenant="${t.id}"><div class="tenant-row-title"><b>${esc(t.company)}</b><span>${esc(t.unit)} · ${num(t.area)} м²</span></div><div class="form-grid"><div class="field"><label>Результат</label><select data-field="status"><option value="ok">Норма</option><option value="problem">Есть проблема</option><option value="not_checked">Не осмотрен</option></select></div><div class="field"><label>Категория проблемы</label><select data-field="category"><option>Протечка</option><option>Электрика</option><option>Вентиляция</option><option>Водоснабжение</option><option>Двери</option><option>Уборка</option><option>Другое</option></select></div><div class="field span2"><label>Комментарий / что обнаружено</label><textarea data-field="notes" maxlength="1000" placeholder="Если всё нормально — можно оставить пустым. При проблеме опишите дефект."></textarea></div><div class="field"><label>Приоритет</label><select data-field="priority"><option value="normal">Обычный</option><option value="high">Высокий</option><option value="critical">Критический</option><option value="low">Низкий</option></select></div><div class="field"><label>Фото при проблеме</label><input data-field="photos" type="file" accept="image/jpeg,image/png,image/webp" multiple></div></div></div>`).join('')||'<div class="empty">На объекте нет арендаторов</div>';}
function openInspectionForm(buildingId=''){nextDraftKey='inspection:'+buildingId;if(!app.data.buildings.length)return toast('Сначала добавьте объект или запросите доступ к нему');const opts=app.data.buildings.map(b=>`<option value="${b.id}" ${b.id===buildingId?'selected':''}>${esc(b.name)}</option>`).join(''),initial=buildingId||app.data.buildings[0]?.id||'';const dt=new Date();dt.setMinutes(dt.getMinutes()-dt.getTimezoneOffset());const local=dt.toISOString().slice(0,16);modal(`<form id="inspectionForm"><div class="modal-head"><div><h3>Регламентный осмотр объекта</h3><div class="building-address">Фотофиксация, проверка арендаторов и автоматическая раздача проблем</div></div><button class="icon-btn" type="button" data-close>×</button></div><div class="modal-body"><div class="warning">Не фотографируйте документы, персональные данные и экраны арендаторов. В отчёт попадает только состояние здания, оборудования и эксплуатационные дефекты.</div><div class="form-grid mt-16"><div class="field"><label>Объект</label><select name="buildingId" id="inspectionBuilding" required>${opts}</select></div><div class="field"><label>Дата и время осмотра</label><input name="occurredAt" type="datetime-local" value="${local}" required></div><div class="field"><label>Общее состояние</label><select name="overallCondition"><option value="ok">Норма</option><option value="attention">Есть замечания</option><option value="critical">Критично</option></select></div><div class="field span2"><label>Общий комментарий</label><textarea name="notes" maxlength="2000" placeholder="Состояние территории, входных групп, фасада, кровли по визуальному осмотру и т. п."></textarea></div></div><div class="section-title"><div><h3>Фото объекта с 3–4 сторон</h3><p>Первые три фотографии обязательны</p></div></div><div class="inspection-photo-fields">${['Фасад / сторона 1','Фасад / сторона 2','Фасад / сторона 3','Фасад / сторона 4 (необязательно)'].map((x,n)=>`<div class="field"><label>${x}</label><input id="exterior${n+1}" type="file" accept="image/jpeg,image/png,image/webp" ${n<3?'required':''}></div>`).join('')}</div><div class="section-title"><div><h3>Проблема общего имущества</h3><p>Заполняется только если при внешнем осмотре найден дефект</p></div></div><div class="inspection-building-finding"><div class="form-grid"><div class="field span2"><label>Что обнаружено</label><input id="buildingFindingTitle" maxlength="160" placeholder="Например: разрушение плитки у входа"></div><div class="field"><label>Категория</label><select id="buildingFindingCategory"><option>Протечка</option><option>Электрика</option><option>Вентиляция</option><option>Водоснабжение</option><option>Двери</option><option>Уборка</option><option>Другое</option></select></div><div class="field"><label>Приоритет</label><select id="buildingFindingPriority"><option value="normal">Обычный</option><option value="high">Высокий</option><option value="critical">Критический</option><option value="low">Низкий</option></select></div><div class="field span2"><label>Комментарий</label><textarea id="buildingFindingNotes"></textarea></div><div class="field span2"><label>Фото дефекта</label><input id="buildingFindingPhotos" type="file" accept="image/jpeg,image/png,image/webp" multiple></div></div></div><div class="section-title"><div><h3>Осмотр арендаторов</h3><p>Для каждого помещения отметьте результат</p></div></div><div id="inspectionTenantRows">${tenantCheckRows(initial)}</div></div><div class="modal-actions"><button class="btn btn-ghost" type="button" data-close>Отмена</button><button class="btn btn-primary" type="submit">Сохранить осмотр</button></div></form>`,true);$$('[data-close]').forEach(x=>x.onclick=closeModal);$('#inspectionBuilding').onchange=e=>{$('#inspectionTenantRows').innerHTML=tenantCheckRows(e.target.value);};$('#inspectionForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.currentTarget);try{const exteriorPhotos=[];for(let n=1;n<=4;n++){const inp=$('#exterior'+n);const photos=await filesToPayload(inp);if(photos[0])exteriorPhotos.push({side:`Сторона ${n}`,photo:photos[0]});}if(exteriorPhotos.length<3)throw new Error('Нужно минимум 3 фотографии объекта с разных сторон');const tenantChecks=[];for(const row of $$('[data-check-tenant]')){const status=$('[data-field="status"]',row).value,notes=$('[data-field="notes"]',row).value,category=$('[data-field="category"]',row).value,priority=$('[data-field="priority"]',row).value,photos=await filesToPayload($('[data-field="photos"]',row));if(status==='problem'&&!notes.trim())throw new Error('Для проблемы арендатора нужно описание');if(status==='problem'&&!photos.length)throw new Error('Для проблемы арендатора нужно фото');tenantChecks.push({tenantId:row.dataset.checkTenant,status,notes,category,priority,photos});}const bfTitle=$('#buildingFindingTitle').value.trim();let buildingFinding=null;if(bfTitle){const photos=await filesToPayload($('#buildingFindingPhotos'));if(!photos.length)throw new Error('Для проблемы объекта приложите фото');buildingFinding={title:bfTitle,category:$('#buildingFindingCategory').value,priority:$('#buildingFindingPriority').value,notes:$('#buildingFindingNotes').value,photos};}const payload={buildingId:fd.get('buildingId'),occurredAt:new Date(fd.get('occurredAt')).toISOString(),overallCondition:fd.get('overallCondition'),notes:fd.get('notes'),exteriorPhotos,tenantChecks,buildingFinding};const r=await api('/api/inspections',{method:'POST',body:JSON.stringify(payload)});await refresh();closeModal();renderShell();toast(`Осмотр сохранён. Создано проблем: ${r.createdIssueIds?.length||0}`);}catch(err){toast(errorText(err));}};}

const equipmentStatuses={ok:'Норма',attention:'Требует внимания',out_of_service:'Не работает'};
const resourceLabels={electricity:['Электричество','кВт⋅ч'],water:['Вода','м³'],heat:['Тепло','Гкал']};
function canManageRecords(kind){return hasPerm(kind+'_view')&&hasPerm(kind+'_manage');}
function todayLocal(){return new Intl.DateTimeFormat('en-CA').format(new Date());}
function recordBuildingOptions(selected='',all=false){return(all?'<option value="">Все объекты</option>':'')+app.data.buildings.map(b=>`<option value="${b.id}" ${b.id===selected?'selected':''}>${esc(b.name)}</option>`).join('');}
function renderEquipment(v){
 v.innerHTML=`<div class="subhead"><div><h2>Оборудование</h2><p>Технический реестр и сроки обслуживания</p></div>${canManageRecords('equipment')?'<button class="btn btn-primary" id="newEquipment">+ Оборудование</button>':''}</div><div class="form-grid"><div class="field"><label for="equipmentSearch">Поиск</label><input id="equipmentSearch" type="search" placeholder="Название, модель, место"></div><div class="field"><label for="equipmentBuilding">Объект</label><select id="equipmentBuilding">${recordBuildingOptions('',true)}</select></div><div class="field"><label for="equipmentState">Состояние</label><select id="equipmentState"><option value="">Все записи</option><option value="due">ТО сегодня или просрочено</option>${Object.entries(equipmentStatuses).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></div></div><div id="equipmentResults"></div>`;
 const render=()=>{const query=$('#equipmentSearch').value.trim().toLowerCase(),bid=$('#equipmentBuilding').value,state=$('#equipmentState').value,today=todayLocal(),rows=(app.data.equipment||[]).filter(e=>(!bid||e.buildingId===bid)&&(!query||[e.name,e.system,e.model,e.location].join(' ').toLowerCase().includes(query))&&(!state||(state==='due'?e.nextService&&e.nextService<=today:e.status===state))).sort((a,b)=>(a.nextService||'9999').localeCompare(b.nextService||'9999'));$('#equipmentResults').innerHTML=`<div class="grid registry-cards">${rows.map(e=>`<article class="card registry-card"><div class="card-head"><div><h3>${esc(e.name)}</h3><span class="muted">${esc(app.data.buildings.find(b=>b.id===e.buildingId)?.name||e.buildingId)}</span></div><span class="tag">${esc(equipmentStatuses[e.status]||e.status)}</span></div><div class="card-body"><dl class="expense-lines"><div><dt>Система</dt><dd>${esc(e.system||'—')}</dd></div><div><dt>Модель</dt><dd>${esc(e.model||'—')}</dd></div><div><dt>Расположение</dt><dd>${esc(e.location||'—')}</dd></div><div><dt>Следующее ТО</dt><dd>${fmtDate(e.nextService)}</dd></div></dl>${e.nextService&&e.nextService<=today?'<p class="service-due">Срок обслуживания наступил</p>':''}<div class="row-actions"><button class="btn btn-secondary" data-equipment="${e.id}">Карточка</button>${canManageRecords('equipment')?`<button class="btn btn-ghost" data-edit-equipment="${e.id}">Редактировать</button>`:''}</div></div></article>`).join('')||'<div class="empty">Оборудование не найдено</div>'}</div>`;$$('[data-equipment]').forEach(b=>b.onclick=()=>openEquipment(b.dataset.equipment));$$('[data-edit-equipment]').forEach(b=>b.onclick=()=>openEquipmentForm(b.dataset.editEquipment));};
 $('#equipmentSearch').oninput=render;$('#equipmentBuilding').onchange=render;$('#equipmentState').onchange=render;$('#newEquipment')?.addEventListener('click',()=>openEquipmentForm());render();
}
function openEquipment(id){const e=(app.data.equipment||[]).find(x=>x.id===id);if(!e)return toast('Оборудование недоступно');modal(`<div class="modal-head"><h3>${esc(e.name)}</h3><button class="icon-btn" data-close>×</button></div><div class="modal-body"><p>${esc(app.data.buildings.find(b=>b.id===e.buildingId)?.name||'')}</p><dl class="expense-lines">${[['Система',e.system],['Модель',e.model],['Расположение',e.location],['Состояние',equipmentStatuses[e.status]],['Следующее ТО',fmtDate(e.nextService)]].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v||'—')}</dd></div>`).join('')}</dl><p>${esc(e.note||'')}</p></div><div class="modal-actions">${canManageRecords('equipment')?'<button class="btn btn-primary" id="equipmentEdit">Редактировать</button>':''}${canManageStaff()?'<button class="btn btn-ghost danger-link" id="equipmentDelete">Удалить</button>':''}<button class="btn btn-ghost" data-close>Закрыть</button></div>`);$$('[data-close]').forEach(b=>b.onclick=closeModal);$('#equipmentEdit')?.addEventListener('click',()=>openEquipmentForm(id));$('#equipmentDelete')?.addEventListener('click',()=>deleteRecord('equipment',id,e.name));}
function openEquipmentForm(id=''){
 if(!canManageRecords('equipment'))return;if(!app.data.buildings.length)return toast('Сначала добавьте объект или запросите доступ');const item=(app.data.equipment||[]).find(e=>e.id===id);nextDraftKey='equipment:'+(id||'new:'+(app.buildingScope||''));
 modal(`<form id="equipmentForm"><div class="modal-head"><h3>${item?'Редактировать оборудование':'Добавить оборудование'}</h3><button class="icon-btn" type="button" data-close>×</button></div><div class="modal-body"><div class="form-grid"><div class="field"><label>Объект</label><select name="buildingId" required ${item?'disabled':''}>${recordBuildingOptions(item?.buildingId||app.buildingScope)}</select></div>${[['name','Название',120],['system','Система',80],['model','Модель',120],['location','Расположение',140]].map(([k,label,max])=>`<div class="field"><label>${label}</label><input name="${k}" maxlength="${max}" value="${esc(item?.[k]||'')}" ${k==='name'?'required':''}></div>`).join('')}<div class="field"><label>Состояние</label><select name="status">${Object.entries(equipmentStatuses).map(([k,label])=>`<option value="${k}" ${k===item?.status?'selected':''}>${label}</option>`).join('')}</select></div><div class="field"><label>Следующее ТО</label><input type="date" name="nextService" value="${esc(item?.nextService||'')}"></div><div class="field span2"><label>Примечание</label><textarea name="note" maxlength="1000">${esc(item?.note||'')}</textarea></div></div></div><div class="modal-actions"><button class="btn btn-ghost" type="button" data-close>Отмена</button><button class="btn btn-primary" type="submit">Сохранить</button></div></form>`);
 bindRegistryForm('equipment',item);
}
function metricChange(item,key){const date=new Date(item.month+'-01T12:00:00Z');if(Number.isNaN(date.getTime()))return '';date.setUTCMonth(date.getUTCMonth()-1);const prev=(app.data.metrics||[]).find(m=>m.buildingId===item.buildingId&&m.month===date.toISOString().slice(0,7));if(!prev)return '';const old=Number(prev[key]),value=Number(item[key]);return old>0?`${value>=old?'+':''}${num(Math.round((value-old)/old*1000)/10)}% к прошлому месяцу`:value>0?'В прошлом месяце — 0':'Без изменений';}
function renderMetrics(v){
 const first=app.data.buildings[0]?.id||'';v.innerHTML=`<div class="subhead"><div><h2>Показатели</h2><p>Потребление за месяц — укажите расход, а не накопленное показание счётчика</p></div>${canManageRecords('metrics')?'<button class="btn btn-primary" id="newMetric">+ Показатели</button>':''}</div><div class="form-grid"><div class="field"><label for="metricBuilding">Объект</label><select id="metricBuilding">${recordBuildingOptions(first,true)}</select></div><div class="field"><label for="metricResource">Ресурс на графике</label><select id="metricResource">${Object.entries(resourceLabels).map(([k,v])=>`<option value="${k}">${v[0]}</option>`).join('')}</select></div></div><div id="metricResults"></div>`;
 const render=()=>{const bid=$('#metricBuilding').value,key=$('#metricResource').value,rows=(app.data.metrics||[]).filter(m=>!bid||m.buildingId===bid).slice().sort((a,b)=>b.month.localeCompare(a.month)),series=rows.slice(0,12).reverse(),max=Math.max(...series.map(m=>Number(m[key])||0),1);$('#metricResults').innerHTML=`${bid&&series.length?`<div class="card"><div class="card-head"><h3>${resourceLabels[key][0]} · последние 12 записей</h3></div><div class="card-body metric-bars">${series.map(m=>`<div class="bar-row"><span>${esc(m.month)}</span><progress class="metric-progress" max="${max}" value="${Number(m[key])||0}" aria-label="${resourceLabels[key][0]} ${esc(m.month)}"></progress><span class="value">${num(m[key])} ${resourceLabels[key][1]}</span></div>`).join('')}</div></div>`:''}<div class="grid registry-cards mt-16">${rows.map(m=>`<article class="card registry-card"><div class="card-head"><div><h3>${esc(m.month)}</h3><span class="muted">${esc(app.data.buildings.find(b=>b.id===m.buildingId)?.name||m.buildingId)}</span></div></div><div class="card-body"><dl class="expense-lines">${Object.entries(resourceLabels).map(([key,[label,unit]])=>`<div><dt>${label}</dt><dd>${num(m[key])} ${unit}<small class="metric-change">${metricChange(m,key)}</small></dd></div>`).join('')}</dl>${m.note?`<p>${esc(m.note)}</p>`:''}<div class="row-actions">${canManageRecords('metrics')?`<button class="btn btn-secondary" data-edit-metric="${m.id}">Редактировать</button>`:''}${canManageStaff()?`<button class="btn btn-ghost danger-link" data-delete-metric="${m.id}">Удалить</button>`:''}</div></div></article>`).join('')||'<div class="empty">Для выбранного объекта показателей пока нет</div>'}</div>`;$$('[data-edit-metric]').forEach(b=>b.onclick=()=>openMetricsForm(b.dataset.editMetric));$$('[data-delete-metric]').forEach(b=>b.onclick=()=>deleteRecord('metrics',b.dataset.deleteMetric,'показатели за выбранный месяц'));};$('#metricBuilding').onchange=render;$('#metricResource').onchange=render;$('#newMetric')?.addEventListener('click',()=>openMetricsForm('', $('#metricBuilding').value));render();
}
function openMetricsForm(id='',buildingId=''){
 if(!canManageRecords('metrics'))return;if(!app.data.buildings.length)return toast('Сначала добавьте объект или запросите доступ');const item=(app.data.metrics||[]).find(e=>e.id===id);nextDraftKey='metrics:'+(id||'new:'+buildingId);
 modal(`<form id="metricsForm"><div class="modal-head"><h3>${item?'Редактировать показатели':'Добавить показатели'}</h3><button class="icon-btn" type="button" data-close>×</button></div><div class="modal-body"><p>Расход ресурсов за выбранный месяц. Если ресурс не используется, укажите 0.</p><div class="form-grid"><div class="field"><label>Объект</label><select name="buildingId" required ${item?'disabled':''}>${recordBuildingOptions(item?.buildingId||buildingId)}</select></div><div class="field"><label>Месяц</label><input type="month" name="month" required value="${esc(item?.month||todayLocal().slice(0,7))}"></div>${Object.entries(resourceLabels).map(([key,[label,unit]])=>`<div class="field"><label>${label}, ${unit}</label><input name="${key}" type="number" min="0" max="1000000000000" step="0.001" required value="${item?.[key]??''}"></div>`).join('')}<div class="field span2"><label>Примечание</label><textarea name="note" maxlength="500">${esc(item?.note||'')}</textarea></div></div></div><div class="modal-actions"><button class="btn btn-ghost" type="button" data-close>Отмена</button><button class="btn btn-primary" type="submit">Сохранить</button></div></form>`);bindRegistryForm('metrics',item);
}
function bindRegistryForm(kind,item){$$('[data-close]').forEach(b=>b.onclick=closeModal);$('#'+kind+'Form').onsubmit=async e=>{e.preventDefault();const body=Object.fromEntries(new FormData(e.currentTarget));try{await api('/api/'+kind+(item?'/'+encodeURIComponent(item.id):''),{method:item?'PATCH':'POST',body:JSON.stringify(body)});await refresh();closeModal();renderShell();toast('Запись сохранена');}catch(err){toast(errorText(err));}};}
async function deleteRecord(kind,id,label){if(!confirm('Удалить '+label+'?'))return;try{await api('/api/'+kind+'/'+encodeURIComponent(id),{method:'DELETE'});await refresh();closeModal();renderShell();toast('Запись удалена');}catch(err){toast(errorText(err));}}

const expenseCategories={electricity:'Электричество',water:'Вода',heat:'Тепло',cleaning:'Уборка',security:'Охрана',repair:'Ремонт'};
function renderExpenses(v){
 const all=app.data.expenses||[],periods=[...new Set(all.map(e=>e.month||''))].sort().reverse();
 v.innerHTML=`<div class="subhead"><div><h2>Эксплуатационные расходы</h2><p>Расходы по объектам и месяцам</p></div>${canManageStaff()?'<button class="btn btn-primary" id="newExpense">+ Расходы</button>':''}</div><div class="form-grid"><div class="field"><label for="expenseBuildingFilter">Объект</label><select id="expenseBuildingFilter"><option value="">Все объекты</option>${app.data.buildings.map(b=>`<option value="${b.id}">${esc(b.name)}</option>`).join('')}</select></div><div class="field"><label for="expensePeriodFilter">Период</label><select id="expensePeriodFilter"><option value="all">Все периоды</option>${periods.map(m=>`<option value="${esc(m)}">${m?esc(m):'Без периода (старые записи)'}</option>`).join('')}</select></div></div><div id="expenseResults"></div>`;
 const render=()=>{const bid=$('#expenseBuildingFilter').value,month=$('#expensePeriodFilter').value,rows=all.filter(e=>(!bid||e.buildingId===bid)&&(month==='all'||(e.month||'')===month)).slice().sort((a,b)=>(b.month||'').localeCompare(a.month||''));$('#expenseResults').innerHTML=`<div class="backup-summary"><b>Всего за выбранные периоды</b><strong>${money(rows.reduce((n,e)=>n+e.total,0))}</strong></div><div class="grid expense-cards">${rows.map(e=>`<article class="card expense-card"><div class="card-head"><div><h3>${esc(app.data.buildings.find(b=>b.id===e.buildingId)?.name||e.buildingId)}</h3><span class="muted">${esc(e.month||'Без периода')}</span></div><strong>${money(e.total)}</strong></div><div class="card-body"><dl class="expense-lines">${Object.entries(expenseCategories).map(([k,label])=>`<div><dt>${label}</dt><dd>${money(e[k])}</dd></div>`).join('')}</dl>${e.note?`<p>${esc(e.note)}</p>`:''}${canManageStaff()?`<div class="row-actions"><button class="btn btn-secondary" data-edit-expense="${e.id}">Редактировать</button><button class="btn btn-ghost danger-link" data-delete-expense="${e.id}">Удалить</button></div>`:''}</div></article>`).join('')||'<div class="empty">За выбранный период расходов нет</div>'}</div>`;$$('[data-edit-expense]').forEach(b=>b.onclick=()=>openExpenseForm(b.dataset.editExpense));$$('[data-delete-expense]').forEach(b=>b.onclick=()=>deleteExpense(b.dataset.deleteExpense));};
 $('#expenseBuildingFilter').onchange=render;$('#expensePeriodFilter').onchange=render;$('#newExpense')?.addEventListener('click',()=>openExpenseForm());render();
}
function openExpenseForm(id=''){
 const item=(app.data.expenses||[]).find(e=>e.id===id);if(!app.data.buildings.length)return toast('Сначала добавьте объект');nextDraftKey='expense:'+(id||'new:'+(app.buildingScope||''));
 modal(`<form id="expenseForm"><div class="modal-head"><h3>${item?'Редактировать расходы':'Добавить расходы'}</h3><button class="icon-btn" type="button" data-close>×</button></div><div class="modal-body"><div class="form-grid"><div class="field"><label>Объект</label><select name="buildingId" required ${item?'disabled':''}>${app.data.buildings.map(b=>`<option value="${b.id}" ${b.id===(item?.buildingId||app.buildingScope)?'selected':''}>${esc(b.name)}</option>`).join('')}</select></div><div class="field"><label>Месяц</label><input type="month" name="month" value="${esc(item?item.month||'':new Date().toISOString().slice(0,7))}" ${item&&!item.month?'':'required'}></div>${Object.entries(expenseCategories).map(([key,label])=>`<div class="field"><label>${label}, ₽</label><input type="number" name="${key}" min="0" max="1000000000000" step="0.01" value="${item?.[key]||0}" required></div>`).join('')}<div class="field span2"><label>Примечание</label><textarea name="note" maxlength="500">${esc(item?.note||'')}</textarea></div></div><p class="expense-total">Итого: <strong id="expenseTotal"></strong></p></div><div class="modal-actions"><button class="btn btn-ghost" type="button" data-close>Отмена</button><button class="btn btn-primary" type="submit">Сохранить</button></div></form>`);
 const form=$('#expenseForm'),total=()=>{$('#expenseTotal').textContent=money(Object.keys(expenseCategories).reduce((n,k)=>n+Math.round(Number(form.elements[k].value||0)*100),0)/100);};form.addEventListener('input',total);form.addEventListener('draftrestored',total);total();$$('[data-close]').forEach(b=>b.onclick=closeModal);
 form.onsubmit=async e=>{e.preventDefault();try{await api('/api/expenses'+(item?'/'+encodeURIComponent(item.id):''),{method:item?'PATCH':'POST',body:JSON.stringify(Object.fromEntries(new FormData(form)))});await refresh();closeModal();renderShell();toast('Расходы сохранены');}catch(err){toast(errorText(err));}};
}
async function deleteExpense(id){const e=app.data.expenses.find(x=>x.id===id);if(!e||!confirm(`Удалить запись расходов за ${e.month||'период без даты'} на ${money(e.total)}?`))return;try{await api('/api/expenses/'+encodeURIComponent(id),{method:'DELETE'});await refresh();renderShell();toast('Запись расходов удалена');}catch(err){toast(errorText(err));}}

function renderAdmin(v){const a=app.data.admin;if(!a)return v.innerHTML='<div class="empty">Нет доступа</div>';const s=a.stats,staff=a.users.filter(u=>!['owner','tenant'].includes(u.role)),staffMap=new Map(a.users.map(u=>[u.id,u]));v.innerHTML=`<div class="subhead"><div><h2>Сотрудники</h2><p>Добавляйте работников, выдавайте доступ и назначайте задания.</p></div><button class="btn btn-primary" id="addStaff">+ Сотрудник</button></div><div class="grid stats"><div class="stat"><div class="stat-label">Активные сотрудники</div><div class="stat-value">${s.activeStaff}</div><div class="stat-foot">${s.disabledStaff} отключено</div></div><div class="stat alert"><div class="stat-label">Открытые проблемы</div><div class="stat-value">${s.openIssues}</div><div class="stat-foot">по всем объектам</div></div><div class="stat"><div class="stat-label">Осмотров за 7 дней</div><div class="stat-value">${s.inspections7d}</div><div class="stat-foot">${s.duePlans} планов на неделе</div></div><div class="stat"><div class="stat-label">Среднее решение</div><div class="stat-value">${s.avgResolutionHours||0} ч</div><div class="stat-foot">по закрытым проблемам</div></div><div class="stat alert"><div class="stat-label">Возвратов арендаторами</div><div class="stat-value">${s.rejected30d}</div><div class="stat-foot">за 30 дней</div></div></div><div class="backup-summary"><b>Резервная копия</b><span>${app.data.backupStatus?.lastBackupAt?fmtDateTime(app.data.backupStatus.lastBackupAt)+' · проверена при создании':'Пока нет подтверждённой копии'}</span>${app.data.backupStatus?.stale?'<strong class="service-due">Требует внимания: свежей копии нет более 36 часов или копии ещё не создавались</strong>':''}${app.data.backupStatus?.lastBackupAt?'<button class="btn btn-secondary" id="downloadBackup">Скачать копию</button>':''}</div><p class="backup-download-help">Копии хранятся на сервере. Скачайте архив и сохраните в защищённом внешнем хранилище. Автоматическое внешнее копирование пока не подключено.</p><div class="card"><div class="card-head"><h3>Сотрудники и доступы</h3><span class="tag">сотрудники</span></div><div class="table-wrap"><table class="table staff-table"><thead><tr><th>Сотрудник</th><th>Роль</th><th>Объекты</th><th>Открытых задач</th><th>Статус</th><th></th></tr></thead><tbody>${staff.map(u=>{const w=s.workload.find(x=>x.userId===u.id);return`<tr><td><b>${esc(u.name)}</b><div class="muted">${esc(u.email)}</div></td><td>${esc(roleLabel(u.role))}</td><td>${(u.buildingIds||[]).map(id=>esc(app.data.buildings.find(b=>b.id===id)?.name||id)).join(', ')||'—'}</td><td data-label="Открытые задачи">${w?.open||0}</td><td><span class="staff-status ${u.active?'active':'disabled'}">${u.active?'Активен':'Отключён'}</span></td><td><div class="row-actions"><button class="link-btn" data-edit-staff="${u.id}">Редактировать</button><button class="link-btn" data-task-staff="${u.id}">Назначить задачу</button><button class="link-btn" data-reset-staff="${u.id}">Управление паролем</button><button class="link-btn ${u.active?'danger-link':''}" data-toggle-staff="${u.id}">${u.active?'Отключить':'Восстановить'}</button></div></td></tr>`;}).join('')}</tbody></table></div></div><div class="grid two mt-16"><div class="card"><div class="card-head"><h3>Автоматическое распределение проблем</h3><button class="link-btn" id="addRoute">+ Маршрут</button></div><div class="card-body"><div class="route-list">${a.routingRules.filter(r=>r.active!==false).map(r=>{const b=r.buildingId==='*'?'Доступные исполнителю объекты':app.data.buildings.find(x=>x.id===r.buildingId)?.name||r.buildingId,u=staffMap.get(r.responsibleUserId);return`<div class="route-row"><div><b>${esc(r.category)}</b><span>${esc(b)}</span></div><strong>→ ${esc(u?.name||'Не назначен')}</strong></div>`;}).join('')}</div></div></div><div class="card"><div class="card-head"><h3>Графики еженедельных осмотров</h3></div><div class="card-body"><div class="route-list">${a.inspectionPlans.map(p=>{const b=app.data.buildings.find(x=>x.id===p.buildingId),u=staffMap.get(p.inspectorUserId);return`<button class="route-row plan-row" data-plan="${p.buildingId}"><div><b>${esc(b?.name||p.buildingId)}</b><span>каждые ${p.frequencyDays} дней · следующий ${fmtDate(p.nextDue)}</span></div><strong>${esc(u?.name||'Не назначен')}</strong></button>`;}).join('')}</div></div></div></div><div class="card mt-16"><div class="card-head"><h3>Нагрузка сотрудников</h3></div><div class="card-body"><div class="workload-grid">${s.workload.map(w=>`<div class="workload-card"><span>${esc(roleLabel(w.role))}</span><strong>${esc(w.name)}</strong><div><b>${w.open}</b> открытых задач · <b>${w.inspections}</b> осмотров / 30 дн.</div></div>`).join('')}</div></div></div>`;$('#downloadBackup')?.addEventListener('click',openBackupDownload);$('#addStaff').onclick=()=>openStaffForm();$$('[data-edit-staff]').forEach(x=>x.onclick=()=>openStaffForm(x.dataset.editStaff));$$('[data-task-staff]').forEach(x=>x.onclick=()=>openStaffTask(x.dataset.taskStaff));$$('[data-reset-staff]').forEach(x=>x.onclick=()=>resetStaffPassword(x.dataset.resetStaff));$$('[data-toggle-staff]').forEach(x=>x.onclick=()=>toggleStaff(x.dataset.toggleStaff));$('#addRoute').onclick=()=>openRouteForm();$$('[data-plan]').forEach(x=>x.onclick=()=>openPlanForm(x.dataset.plan));}
function openBackupDownload(){modal(`<div class="modal-head"><h3>Скачать резервную копию</h3><button class="icon-btn" data-close>×</button></div><div class="modal-body"><p>Архив содержит рабочие данные, учётные записи с хешами паролей и фотографии. Доступен только владельцу.</p><p>Перед скачиванием сервер повторно проверяет целостность. Копия от ${fmtDateTime(app.data.backupStatus?.lastBackupAt)}. Данные, добавленные позже, в неё не входят.</p><p>Храните архив в защищённом месте. При отсутствии связи или ошибке скачивания повторите попытку. Секреты настройки сервера в архив не входят.</p></div><div class="modal-actions"><a class="btn btn-primary" href="/api/backups/download" target="_blank" rel="noopener">Скачать архив</a><button class="btn btn-ghost" data-close>Закрыть</button></div>`);$$('[data-close]').forEach(b=>b.onclick=closeModal);}
function permissionsChecks(selected=[]){const labels={dashboard_view:'Обзор',buildings_view:'Объекты',tenants_view:'Видеть арендаторов',tenants_manage:'Добавлять и редактировать арендаторов',issues_view:'Видеть проблемы',issues_edit:'Назначать и решать проблемы',inspections_view:'Видеть осмотры',inspections_create:'Проводить осмотры',equipment_view:'Видеть оборудование',equipment_manage:'Добавлять и изменять оборудование',metrics_view:'Видеть показатели',metrics_manage:'Добавлять и изменять показатели',expenses_view:'Расходы',security_view:'Безопасность'};const perms=app.data.admin.permissions;return`<div class="permission-grid">${perms.map(p=>`<label class="perm"><input type="checkbox" name="permissions" value="${p}" ${selected.includes(p)?'checked':''}><span><b>${esc(labels[p]||p)}</b></span></label>`).join('')}</div>`;}
function openStaffForm(id=''){
  const a=app.data.admin,u=id?a.users.find(x=>x.id===id):null,role=u?.role||'manager',selected=u?.permissions||a.roleDefaults[role]||[];
  modal(`<form id="staffForm"><div class="modal-head"><div><h3>${u?'Редактировать сотрудника':'Добавить сотрудника'}</h3><div class="building-address">Учётная запись, роль, объекты и рабочие права</div></div><button class="icon-btn" data-close type="button">×</button></div><div class="modal-body"><div class="form-grid"><div class="field"><label>Имя сотрудника</label><input name="name" value="${esc(u?.name||'')}" required maxlength="100"></div><div class="field"><label>Логин / email</label><input name="email" type="text" value="${esc(u?.email||'')}" required autocomplete="off"></div><div class="field"><label>Роль</label><select name="role" id="staffRole">${a.roles.map(r=>`<option value="${r}" ${r===role?'selected':''}>${esc(roleLabel(r))}</option>`).join('')}</select></div><div class="field"><label>${u?'Новый пароль (если нужно)':'Пароль'}</label><input name="password" type="password" minlength="10" autocomplete="new-password" placeholder="${u?'Оставьте пустым, чтобы не менять':'Можно оставить пустым — создадим временный'}"><div class="field-help">Минимум 10 символов. При смене пароля активные сеансы сотрудника завершатся.</div></div></div><div class="section-title"><div><h3>Доступ к объектам</h3></div></div><div class="permission-grid">${app.data.buildings.map(b=>`<label class="perm"><input type="checkbox" name="buildingIds" value="${b.id}" ${(u?.buildingIds||app.data.buildings.map(x=>x.id)).includes(b.id)?'checked':''}><span><b>${esc(b.name)}</b><small>${esc(b.address)}</small></span></label>`).join('')}</div><div class="section-title"><div><h3>Права</h3><p>Оставьте только необходимые сотруднику функции</p></div></div><div id="staffPermissions">${permissionsChecks(selected)}</div></div><div class="modal-actions"><button class="btn btn-ghost" data-close type="button">Отмена</button><button class="btn btn-primary" type="submit">${u?'Сохранить сотрудника':'Создать сотрудника'}</button></div></form>`,true);
  $$('[data-close]').forEach(x=>x.onclick=closeModal);
  $('#staffRole').onchange=e=>{if(!u)$('#staffPermissions').innerHTML=permissionsChecks(a.roleDefaults[e.target.value]||[]);};
  $('#staffForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.currentTarget),payload={name:fd.get('name'),email:fd.get('email'),role:fd.get('role'),buildingIds:fd.getAll('buildingIds'),permissions:fd.getAll('permissions')};if(fd.get('password'))payload.password=fd.get('password');try{if(u){await api('/api/staff/'+encodeURIComponent(u.id),{method:'PATCH',body:JSON.stringify(payload)});await refresh();closeModal();renderShell();toast('Данные сотрудника обновлены');}else{const r=await api('/api/staff',{method:'POST',body:JSON.stringify(payload)});closeModal();showTempPassword(r.user,r.temporaryPassword);await refresh();renderShell();}}catch(err){toast(errorText(err));}};
}
function staffCan(u,kind,buildingId=''){return u.active!==false&&u.role!=='tenant'&&(u.role==='owner'||((u.permissions||[]).includes(kind+'_view')&&(u.permissions||[]).includes(kind==='issues'?'issues_edit':'inspections_create')&&(!buildingId||buildingId==='*'||(u.buildingIds||[]).includes(buildingId))));}
function openStaffTask(id){const u=app.data.admin.users.find(x=>x.id===id);if(!u||u.active===false)return toast('Сотрудник отключён');if(!staffCan(u,'issues'))return toast('Сначала выдайте сотруднику права на просмотр и выполнение задач');const buildingId=(u.buildingIds||[]).find(b=>app.data.buildings.some(x=>x.id===b))||'';if(!buildingId)return toast('Сначала выдайте сотруднику доступ к объекту');openIssueForm('',buildingId,u.id);}
function showTempPassword(user,pwd){modal(`<div class="modal-head"><h3>Сотрудник создан</h3><button class="icon-btn" data-close>×</button></div><div class="modal-body"><div class="success-note">Временный пароль показывается только сейчас. Передайте его сотруднику безопасным способом.</div><div class="credential-box"><span>${esc(user.email)}</span><strong>${esc(pwd)}</strong></div></div><div class="modal-actions"><button class="btn btn-primary" id="copyPwd">Скопировать пароль</button><button class="btn btn-ghost" data-close>Готово</button></div>`);$$('[data-close]').forEach(x=>x.onclick=closeModal);$('#copyPwd').onclick=async()=>{try{await navigator.clipboard.writeText(pwd);toast('Пароль скопирован');}catch{toast('Скопируйте пароль вручную');}};}
async function toggleStaff(id){const u=app.data.admin.users.find(x=>x.id===id);if(!u)return;if(u.active&&!confirm(`Отключить доступ сотруднику ${u.name}? Его активные сессии будут завершены.`))return;try{await api('/api/staff/'+encodeURIComponent(id),{method:'PATCH',body:JSON.stringify({active:!u.active})});await refresh();renderShell();toast(u.active?'Доступ отключён':'Доступ восстановлен');}catch(err){toast(errorText(err));}}
function resetStaffPassword(id){const u=app.data.admin.users.find(x=>x.id===id);if(!u)return;modal(`<form id="staffPasswordForm"><div class="modal-head"><div><h3>Управление паролем</h3><div class="building-address">${esc(u.name)} · ${esc(u.email)}</div></div><button class="icon-btn" data-close type="button">×</button></div><div class="modal-body"><div class="warning">После назначения нового пароля все активные сеансы сотрудника будут завершены.</div><div class="field"><label>Новый пароль</label><input name="password" type="password" minlength="10" required autocomplete="new-password"><div class="field-help">Не менее 10 символов.</div></div></div><div class="modal-actions"><button class="btn btn-ghost" data-close type="button">Отмена</button><button class="btn btn-secondary" id="generateStaffPassword" type="button">Создать временный</button><button class="btn btn-primary" type="submit">Назначить пароль</button></div></form>`);$$('[data-close]').forEach(x=>x.onclick=closeModal);$('#generateStaffPassword').onclick=async()=>{if(!confirm(`Создать новый временный пароль для ${u.name}?`))return;try{const r=await api('/api/staff/'+encodeURIComponent(id)+'/reset-password',{method:'POST',body:'{}'});showTempPassword(u,r.temporaryPassword);}catch(err){toast(errorText(err));}};$('#staffPasswordForm').onsubmit=async e=>{e.preventDefault();const password=new FormData(e.currentTarget).get('password');try{await api('/api/staff/'+encodeURIComponent(id),{method:'PATCH',body:JSON.stringify({password})});closeModal();toast('Новый пароль назначен');}catch(err){toast(errorText(err));}};}
function openRouteForm(){const staff=app.data.admin.users.filter(u=>u.role!=='owner'&&staffCan(u,'issues')&&(u.buildingIds||[]).some(id=>app.data.buildings.some(b=>b.id===id)));modal(`<form id="routeForm"><div class="modal-head"><h3>Маршрут проблемы</h3><button class="icon-btn" data-close type="button">×</button></div><div class="modal-body"><div class="form-grid"><div class="field"><label>Объект</label><select name="buildingId"><option value="*">Все доступные исполнителю объекты</option>${app.data.buildings.map(b=>`<option value="${b.id}">${esc(b.name)}</option>`).join('')}</select></div><div class="field"><label>Категория</label><select name="category"><option>Протечка</option><option>Электрика</option><option>Вентиляция</option><option>Водоснабжение</option><option>Двери</option><option>Уборка</option><option>Другое</option></select></div><div class="field span2"><label>Автоматически назначать</label><select name="responsibleUserId">${staff.map(u=>`<option value="${u.id}">${esc(u.name)} · ${esc(roleLabel(u.role))}</option>`).join('')}</select></div></div></div><div class="modal-actions"><button class="btn btn-ghost" data-close type="button">Отмена</button><button class="btn btn-primary" type="submit">Сохранить</button></div></form>`);$$('[data-close]').forEach(x=>x.onclick=closeModal);const rf=$('#routeForm');rf.elements.responsibleUserId.required=true;rf.elements.buildingId.onchange=()=>{rf.elements.responsibleUserId.innerHTML='<option value="">Выберите исполнителя</option>'+staff.filter(u=>staffCan(u,'issues',rf.elements.buildingId.value)).map(u=>`<option value="${u.id}">${esc(u.name)}</option>`).join('');};$('#routeForm').onsubmit=async e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.currentTarget));try{await api('/api/routing-rules',{method:'POST',body:JSON.stringify(o)});await refresh();closeModal();renderShell();toast('Маршрут сохранён');}catch(err){toast(errorText(err));}};}
function openPlanForm(buildingId){const p=app.data.admin.inspectionPlans.find(x=>x.buildingId===buildingId),b=app.data.buildings.find(x=>x.id===buildingId),staff=app.data.admin.users.filter(u=>staffCan(u,'inspections',buildingId));modal(`<form id="planForm"><div class="modal-head"><div><h3>График осмотров</h3><div class="building-address">${esc(b?.name||'')}</div></div><button class="icon-btn" data-close type="button">×</button></div><div class="modal-body"><div class="form-grid"><div class="field"><label>Периодичность, дней</label><input name="frequencyDays" type="number" min="1" max="90" value="${p.frequencyDays}" required></div><div class="field"><label>Следующий осмотр</label><input name="nextDue" type="date" value="${esc(p.nextDue)}" required></div><div class="field span2"><label>Инспектор</label><select name="inspectorUserId"><option value="">Не назначен</option>${staff.map(u=>`<option value="${u.id}" ${u.id===p.inspectorUserId?'selected':''}>${esc(u.name)} · ${esc(roleLabel(u.role))}</option>`).join('')}</select></div></div></div><div class="modal-actions"><button class="btn btn-ghost" data-close type="button">Отмена</button><button class="btn btn-primary" type="submit">Сохранить</button></div></form>`);$$('[data-close]').forEach(x=>x.onclick=closeModal);$('#planForm').onsubmit=async e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.currentTarget));try{await api('/api/inspection-plans/'+encodeURIComponent(buildingId),{method:'PATCH',body:JSON.stringify(o)});await refresh();closeModal();renderShell();toast('График обновлён');}catch(err){toast(errorText(err));}};}

function openNotifications(){const rows=app.data.notifications||[];modal(`<div class="modal-head"><div><h3>Уведомления</h3><div class="building-address">Сроки задач и осмотров, назначения и результаты</div></div><button class="icon-btn" data-close>×</button></div><div class="modal-body"><div class="notification-list">${rows.map(n=>`<button class="notification-row ${n.readAt?'':'unread'}" ${n.equipmentId?`data-notify-equipment="${esc(n.equipmentId)}"`:n.issueId?`data-notify-issue="${esc(n.issueId)}"`:n.buildingId?`data-notify-building="${esc(n.buildingId)}"`:''}><div><b>${esc(n.title)}</b><span>${fmtDateTime(n.at)}</span></div><p>${esc(n.text)}</p></button>`).join('')||'<div class="empty">Уведомлений пока нет</div>'}</div></div><div class="modal-actions"><button class="btn btn-ghost" data-close>Закрыть</button></div>`);$$('[data-close]').forEach(x=>x.onclick=closeModal);$$('[data-notify-issue]').forEach(x=>x.onclick=()=>{const id=x.dataset.notifyIssue;closeModal();openIssue(id);});$$('[data-notify-building]').forEach(x=>x.onclick=()=>{closeModal();openBuilding(x.dataset.notifyBuilding);});$$('[data-notify-equipment]').forEach(x=>x.onclick=()=>{const id=x.dataset.notifyEquipment;closeModal();openEquipment(id);});const unread=rows.filter(n=>!n.readAt).map(n=>n.id);if(unread.length){api('/api/notifications/read',{method:'POST',body:JSON.stringify({ids:unread})}).then(()=>{const at=new Date().toISOString();for(const n of rows)if(unread.includes(n.id))n.readAt=at;}).catch(()=>{});}}

function renderSecurity(v){const s=app.data.security;if(!s)return;v.innerHTML=`<div class="subhead"><div><h2>Безопасность</h2><p>Контроль сессий и действий пользователей</p></div></div><div class="grid security-grid"><div class="security-card"><span>Активные сессии</span><strong>${s.sessions}</strong></div><div class="security-card"><span>Ошибки входа / минута</span><strong>${s.failedLastMinute}</strong></div><div class="security-card"><span>Публичная регистрация</span><strong class="registration-off">Выключена</strong></div></div><div class="card mt-16"><div class="card-head"><h3>Журнал действий</h3><span class="tag">только чтение</span></div><div class="card-body"><div class="log">${s.log.map(x=>`<div class="log-row"><div class="time">${esc(x.at)}</div><div><b>${esc(x.actor)}</b></div><div>${esc(x.event)}</div></div>`).join('')}</div></div></div><div class="card mt-16"><div class="card-head"><h3>Политика данных</h3></div><div class="card-body"><div class="info-list"><div class="info-item"><div class="k">Договоры и счета</div><div class="v">Не хранятся</div></div><div class="info-item"><div class="k">Фото осмотров</div><div class="v">Только приватный API</div></div><div class="info-item"><div class="k">PWA-кэш</div><div class="v">Только оболочка</div></div><div class="info-item"><div class="k">Уволенные сотрудники</div><div class="v">Сессии завершаются сразу</div></div></div></div></div>`;}

function setupInspectionSteps(form){
 const body=$('.modal-body',form),children=[...body.children],panels=[0,1,2].map(()=>document.createElement('section'));
 panels.forEach((p,n)=>{p.dataset.inspectionStep=n;body.append(p);});
 children.slice(0,4).forEach(n=>panels[0].append(n));children.slice(4).forEach(n=>panels[1].append(n));
 const nav=document.createElement('nav');nav.className='inspection-steps';nav.setAttribute('aria-label','Шаги осмотра');body.prepend(nav);
 const labels=['1. Объект и фото','2. Помещения','3. Проверка'];let current=0;
 const actions=$('.modal-actions',form),submit=$('[type="submit"]',actions),prev=document.createElement('button'),next=document.createElement('button');
 prev.id='inspectionPrevious';next.id='inspectionNext';prev.type=next.type='button';prev.className='btn btn-secondary';next.className='btn btn-primary';prev.textContent='Назад';next.textContent='Далее';actions.insertBefore(prev,submit);actions.insertBefore(next,submit);
 function summary(){
  const rows=$$('[data-check-tenant]',form),problems=rows.filter(r=>$('[data-field="status"]',r).value==='problem').length,unchecked=rows.filter(r=>$('[data-field="status"]',r).value==='not_checked').length;
  panels[2].innerHTML=`<h3>Проверьте перед отправкой</h3><dl class="expense-lines"><div><dt>Объект</dt><dd>${esc(form.elements.buildingId.selectedOptions[0]?.textContent)}</dd></div><div><dt>Фото объекта</dt><dd>${[1,2,3,4].filter(n=>$('#exterior'+n,form).files.length).length}</dd></div><div><dt>Помещений</dt><dd>${rows.length}</dd></div><div><dt>Замечания по помещениям</dt><dd>${problems}</dd></div><div><dt>Не осмотрено</dt><dd>${unchecked}</dd></div><div><dt>Дефект общего имущества</dt><dd>${$('#buildingFindingTitle',form).value.trim()?'Есть':'Не указан'}</dd></div></dl><p>После сохранения замечания появятся в заданиях объекта.</p>`;
 }
 function show(step){current=step;panels.forEach((p,n)=>p.hidden=n!==step);prev.hidden=step===0;next.hidden=step===2;submit.hidden=step!==2;$$('button',nav).forEach((b,n)=>b.setAttribute('aria-current',n===step?'step':'false'));if(step===2)summary();}
 function valid(step){
  for(const input of $$('input,select,textarea',panels[step]))if(!input.checkValidity()){show(step);input.reportValidity();return false;}
  if(step===1){
   const bad=$$('[data-check-tenant]',form).find(r=>$('[data-field="status"]',r).value==='problem'&&(!$('[data-field="notes"]',r).value.trim()||!$('[data-field="photos"]',r).files.length));
   if(bad){show(1);bad.scrollIntoView({block:'center'});toast('Для каждого замечания добавьте описание и фото.');return false;}
   if($('#buildingFindingTitle',form).value.trim()&&!$('#buildingFindingPhotos',form).files.length){show(1);$('#buildingFindingPhotos',form).scrollIntoView({block:'center'});toast('Добавьте фото дефекта общего имущества.');return false;}
  }return true;
 }
 function go(step){if(step>current)for(let n=0;n<step;n++)if(!valid(n))return;show(step);$('.modal').scrollTop=0;}
 labels.forEach((label,n)=>{const button=document.createElement('button');button.type='button';button.textContent=label;button.onclick=()=>go(n);nav.append(button);});prev.onclick=()=>go(current-1);next.onclick=()=>go(current+1);
 form.addEventListener('invalid',e=>{const panel=e.target.closest('[data-inspection-step]');if(panel)show(Number(panel.dataset.inspectionStep));},true);
 form.addEventListener('submit',e=>{if(current!==2){e.preventDefault();e.stopImmediatePropagation();go(current+1);return;}if(!valid(0)||!valid(1)){e.preventDefault();e.stopImmediatePropagation();}},true);
 show(0);
}

let nextDraftKey='';
function modal(html,wide=false){
 const key=nextDraftKey;nextDraftKey='';const current=$('#modal');if(current?.dataset.buildingId)app.objectReturn={id:current.dataset.buildingId,scroll:$('.modal',current).scrollTop};if(!closeModal())return;
 const bg=document.createElement('div');bg.id='modal';bg.className='modal-backdrop';bg.innerHTML=`<div class="modal ${wide?'modal-wide':''}">${html}</div>`;document.body.appendChild(bg);bg.onclick=e=>{if(e.target===bg)closeModal('back');};
 simplifyForm(bg.querySelector('form'));PhotoInputs.attach(bg.querySelector('form'));
 if(app.objectReturn){const back=$('.modal-head [data-close]',bg);if(back){back.textContent='←';back.setAttribute('aria-label','Назад к объекту');}}
 bindSavedPhotoActions(bg);
 queueMicrotask(()=>{const form=bg.querySelector('form');if(form&&bg.isConnected)FormSafety.attach(form,{key,userId:app.user?.id||'',onSubmitting:f=>app.submittingForm=f,onFinished:f=>{if(app.submittingForm===f)app.submittingForm=null;}});});
}
function simplifyForm(form){
 if(!form)return;
 const optional={buildingForm:['occupied','floors','powerKw','status','manager','note'],issueForm:['tenantId','category','priority'],tenantForm:['floor','contact','phone','ownerResponsible','note'],equipmentForm:['system','model','note'],metricsForm:['note']};
 const names=optional[form.id]||[];
 if(form.id==='issueForm'&&!canManageStaff())names.push('responsibleUserId','due');
 const fields=names.map(name=>form.elements[name]?.closest('.field')).filter(Boolean);
 if(fields.length){const details=foldElements($('.modal-body',form),fields,'Дополнительные поля');details.classList.add('optional-fields');}
 if(form.id==='issueForm'&&canManageStaff()){
  const due=form.elements.due,buttons=document.createElement('div');buttons.className='due-shortcuts';
  for(const [label,days]of [['Сегодня',0],['Завтра',1],['Через неделю',7]]){const button=document.createElement('button');button.type='button';button.className='btn btn-ghost';button.textContent=label;button.onclick=()=>{const d=new Date();d.setDate(d.getDate()+days);due.value=new Intl.DateTimeFormat('en-CA').format(d);due.dispatchEvent(new Event('change',{bubbles:true}));};buttons.append(button);}due.after(buttons);
 }
 if(form.id==='inspectionForm')setupInspectionSteps(form);
 if(form.id==='staffForm'){
  const permissions=$('#staffPermissions',form),title=permissions?.previousElementSibling;
  foldElements($('.modal-body',form),[title,permissions],'Настроить права вручную');
 }
 form.addEventListener('invalid',e=>{let node=e.target.parentElement;while(node&&node!==form){if(node.tagName==='DETAILS')node.open=true;node=node.parentElement;}},true);
}

function closeModal(force=false){
 const form=$('#modal form');if(force!==true&&form?.dataset.saved!=='1'){
  if(form?.dataset.busy==='1'){toast('Дождитесь завершения сохранения');return false;}
  if(form?.dataset.dirty==='1'&&!confirm(form.dataset.draftKey?'Закрыть форму? Черновик останется на этом устройстве. Проверьте сообщение о сохранении фотографий.':'Закрыть форму без сохранения изменений?'))return false;
 }
 PhotoInputs.dispose(form);$('#modal')?.remove();
 if((force==='back'||force instanceof Event)&&app.objectReturn){const back=app.objectReturn;app.objectReturn=null;openBuilding(back.id);const panel=$('#modal .modal');if(panel)panel.scrollTop=back.scroll;}
 if(refreshPending)setTimeout(refreshVisible,0);return true;
}

function openTenantForm(id=''){
 const t=app.data.tenants.find(t=>t.id===id);if(!app.data.buildings.length)return toast('Сначала добавьте объект');nextDraftKey='tenant:'+(id||'new:'+(app.buildingScope||''));
 const field=(name,label,type='text',extra='')=>`<div class="field"><label>${label}</label><input name="${name}" type="${type}" value="${esc(t?.[name]??'')}" ${extra}></div>`;
 modal(`<form id="tenantForm"><div class="modal-head"><h3>${t?'Редактировать арендатора':'Добавить арендатора'}</h3><button class="icon-btn" type="button" data-close>×</button></div><div class="modal-body"><div class="form-grid"><div class="field"><label>Объект</label><select name="buildingId" required ${t?'disabled':''}>${app.data.buildings.map(b=>`<option value="${b.id}" ${b.id===(t?.buildingId||app.buildingScope)?'selected':''}>${esc(b.name)}</option>`).join('')}</select></div>${field('company','Название','text','required maxlength="100"')}${field('unit','Помещение')}${field('area','Площадь, м²','number','min="0.01" step="0.01" required')}${field('floor','Этаж','number','min="-10" max="300"')}${field('contact','Контакт')}${field('phone','Телефон','tel')}${field('ownerResponsible','Ответственный собственника')}<div class="field span2"><label>Рабочее примечание</label><textarea name="note" maxlength="500">${esc(t?.note||'')}</textarea></div></div></div><div class="modal-actions"><button class="btn btn-ghost" type="button" data-close>Отмена</button><button class="btn btn-primary" type="submit">${t?'Сохранить':'Добавить'}</button></div></form>`);
 $$('[data-close]').forEach(x=>x.onclick=closeModal);$('#tenantForm').onsubmit=async e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.currentTarget));try{const saved=await api('/api/tenants'+(t?'/'+encodeURIComponent(t.id):''),{method:t?'PATCH':'POST',body:JSON.stringify(o)});await refresh();closeModal();renderShell();if(t)openTenant(saved.id);toast(t?'Арендатор обновлён':'Арендатор добавлен');}catch(err){toast(errorText(err));}};
}
function assigneeOptions(selected='',buildingId=''){return`<option value="">Не назначен</option>${(app.data.assignees||app.data.admin?.users||[]).filter(u=>u.active!==false&&u.role!=='tenant'&&u.role!=='owner'&&(!buildingId||(u.buildingIds||[]).includes(buildingId))).map(u=>`<option value="${u.id}" ${u.id===selected?'selected':''}>${esc(u.name)} · ${esc(roleLabel(u.role))}</option>`).join('')}`;}
function openIssueForm(tenantId='',buildingId='',responsibleUserId=''){nextDraftKey='issue:'+tenantId+':'+buildingId+':'+responsibleUserId;if(!app.data.buildings.length)return toast('Сначала добавьте объект или запросите доступ к нему');const ownerish=staffMode(),tenantOptions=app.data.tenants.map(t=>`<option value="${t.id}" ${t.id===tenantId?'selected':''}>${esc(t.company)} · ${esc(t.unit)}</option>`).join(''),buildingOptions=app.data.buildings.map(b=>`<option value="${b.id}" ${b.id===buildingId?'selected':''}>${esc(b.name)}</option>`).join('');modal(`<form id="issueForm"><div class="modal-head"><h3>${ownerish?'Создать задание':'Сообщить о проблеме'}</h3><button class="icon-btn" type="button" data-close>×</button></div><div class="modal-body"><div class="form-grid">${ownerish?`<div class="field"><label>Объект</label><select name="buildingId" required>${buildingOptions}</select></div><div class="field"><label>Арендатор</label><select name="tenantId"><option value="">Общая проблема объекта</option>${tenantOptions}</select></div>`:''}<div class="field span2"><label>Что нужно сделать</label><input name="title" required maxlength="160"></div><div class="field"><label>Категория</label><select name="category"><option>Протечка</option><option>Электрика</option><option>Вентиляция</option><option>Водоснабжение</option><option>Двери</option><option>Уборка</option><option selected>Другое</option></select></div><div class="field"><label>Приоритет</label><select name="priority"><option value="normal">Обычный</option><option value="high">Высокий</option><option value="critical">Критический</option><option value="low">Низкий</option></select></div>${ownerish?`<div class="field"><label>Исполнитель</label><select name="responsibleUserId">${assigneeOptions(responsibleUserId)}</select></div><div class="field"><label>Срок</label><input name="due" type="date"></div>`:''}<div class="field span2"><label>Фотографии проблемы</label><input id="issuePhotos" type="file" accept="image/jpeg,image/png,image/webp" multiple><div class="field-help">До 5 фото. Крупные снимки уменьшим перед отправкой. Ненужное фото можно убрать.</div></div></div></div><div class="modal-actions"><button class="btn btn-ghost" type="button" data-close>Отмена</button><button class="btn btn-primary" type="submit">Создать</button></div></form>`);$$('[data-close]').forEach(x=>x.onclick=closeModal);if(ownerish){const form=$('#issueForm'),building=form.elements.buildingId;const updateOptions=()=>{const id=building.value,selected=form.elements.responsibleUserId.value;form.elements.responsibleUserId.innerHTML='<option value="">Не назначен</option>'+(app.data.assignees||[]).filter(u=>(u.buildingIds||[]).includes(id)).map(u=>`<option value="${u.id}" ${u.id===selected?'selected':''}>${esc(u.name)}</option>`).join('');const tid=form.elements.tenantId.value;form.elements.tenantId.innerHTML='<option value="">Общая проблема объекта</option>'+app.data.tenants.filter(t=>t.buildingId===id).map(t=>`<option value="${t.id}" ${t.id===tid?'selected':''}>${esc(t.company)}</option>`).join('');};building.onchange=updateOptions;updateOptions();}
$('#issueForm').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,o=Object.fromEntries(new FormData(form));if(!form.dataset.requestId)form.dataset.requestId=Array.from(crypto.getRandomValues(new Uint8Array(16)),n=>n.toString(16).padStart(2,'0')).join('');try{const photos=await filesToPayload($('#issuePhotos'));await api('/api/issues',{method:'POST',body:JSON.stringify({...o,photos,clientRequestId:form.dataset.requestId})});await refresh();closeModal();renderShell();toast('Проблема создана');}catch(err){toast(errorText(err));}};}
function openIssuePhotoForm(i){nextDraftKey='photos:'+i.id;modal(`<form id="issuePhotoForm"><div class="modal-head"><h3>Добавить фото проблемы</h3><button class="icon-btn" type="button" data-close>×</button></div><div class="modal-body"><div class="field"><label>Фотографии</label><input id="moreIssuePhotos" type="file" accept="image/jpeg,image/png,image/webp" multiple required></div></div><div class="modal-actions"><button class="btn btn-ghost" type="button" data-close>Отмена</button><button class="btn btn-primary" type="submit">Сохранить</button></div></form>`);$$('[data-close]').forEach(x=>x.onclick=closeModal);$('#issuePhotoForm').onsubmit=async e=>{e.preventDefault();try{const photos=await filesToPayload($('#moreIssuePhotos'));if(!photos.length)throw new Error('Выберите фотографию');await api('/api/issues/'+encodeURIComponent(i.id)+'/photos',{method:'POST',body:JSON.stringify({kind:'problem',photos})});await refresh();closeModal();openIssue(i.id);toast('Фото добавлены');}catch(err){toast(errorText(err));}};}
function openReportForm(i,closeMode=false){nextDraftKey='report:'+i.id+':'+closeMode;const suggested=i.responsible||i.executor||app.user.name;modal(`<form id="reportForm"><div class="modal-head"><h3>Отчёт по решению</h3><button class="icon-btn" type="button" data-close>×</button></div><div class="modal-body"><div class="form-grid"><div class="field span2"><label>Кто выполнял работу / подпись</label><input name="author" value="${esc(suggested)}" required></div><div class="field span2"><label>Что сделано</label><textarea name="text" required maxlength="1500"></textarea></div><div class="field span2"><label>Фотоотчёт</label><input id="reportPhotos" type="file" accept="image/jpeg,image/png,image/webp" multiple required></div><div class="field span2"><label class="check-row"><input name="markDone" type="checkbox" value="1" ${closeMode?'checked':''}><span><b>Проблема полностью решена</b><small>Для арендатора результат уйдёт на подтверждение.</small></span></label></div></div></div><div class="modal-actions"><button class="btn btn-ghost" type="button" data-close>Отмена</button><button class="btn btn-primary" type="submit">Добавить отчёт</button></div></form>`);$$('[data-close]').forEach(x=>x.onclick=closeModal);$('#reportForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.currentTarget);try{const photos=await filesToPayload($('#reportPhotos'));if(!photos.length)throw new Error('Добавьте хотя бы одно фото');await api('/api/issues/'+encodeURIComponent(i.id)+'/reports',{method:'POST',body:JSON.stringify({author:fd.get('author'),text:fd.get('text'),markDone:fd.get('markDone')==='1',photos})});await refresh();closeModal();openIssue(i.id);toast('Фотоотчёт сохранён');}catch(err){toast(errorText(err));}};}
function openTenantDecisionForm(i,decision){const accepted=decision==='accepted';modal(`<form id="tenantDecisionForm"><div class="modal-head"><h3>${accepted?'Подтвердить устранение':'Проблема осталась'}</h3><button class="icon-btn" type="button" data-close>×</button></div><div class="modal-body"><div class="field"><label>${accepted?'Комментарий':'Что осталось нерешённым'}</label><textarea name="comment" ${accepted?'':'required'}></textarea></div><div class="field"><label>Фото (необязательно)</label><input id="tenantDecisionPhotos" type="file" accept="image/jpeg,image/png,image/webp" multiple></div></div><div class="modal-actions"><button class="btn btn-ghost" type="button" data-close>Отмена</button><button class="btn ${accepted?'btn-primary':'btn-danger'}" type="submit">${accepted?'Подтвердить':'Вернуть в работу'}</button></div></form>`);$$('[data-close]').forEach(x=>x.onclick=closeModal);$('#tenantDecisionForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.currentTarget);try{const photos=await filesToPayload($('#tenantDecisionPhotos'));await api('/api/issues/'+encodeURIComponent(i.id)+'/tenant-decision',{method:'POST',body:JSON.stringify({decision,comment:fd.get('comment')||'',photos})});await refresh();closeModal();openIssue(i.id);toast(accepted?'Проблема принята':'Проблема возвращена в работу');}catch(err){toast(errorText(err));}};}
function openIssueEdit(i){modal(`<form id="issueEdit"><div class="modal-head"><h3>Назначить / изменить</h3><button class="icon-btn" type="button" data-close>×</button></div><div class="modal-body"><div class="warning">Закрывайте проблему только через итоговый фотоотчёт.</div><div class="form-grid mt-16"><div class="field"><label>Статус</label><select name="status">${Object.entries(statusMap).filter(([k])=>!['done','awaiting_acceptance'].includes(k)||k===i.status).map(([k,val])=>`<option value="${k}" ${i.status===k?'selected':''}>${val}</option>`).join('')}</select></div><div class="field"><label>Приоритет</label><select name="priority">${Object.entries(priorityMap).map(([k,val])=>`<option value="${k}" ${i.priority===k?'selected':''}>${val}</option>`).join('')}</select></div><div class="field span2"><label>Ответственный</label><select name="responsibleUserId">${assigneeOptions(i.responsibleUserId,i.buildingId)}</select></div><div class="field"><label>Исполнитель / подрядчик</label><input name="executor" value="${esc(i.executor||'')}"></div><div class="field"><label>Срок</label><input name="due" type="date" value="${esc(i.due||'')}"></div><div class="field"><label>Стоимость</label><input name="cost" type="number" min="0" value="${Number(i.cost||0)}"></div></div></div><div class="modal-actions"><button class="btn btn-ghost" type="button" data-close>Отмена</button><button class="btn btn-primary" type="submit">Сохранить</button></div></form>`);$$('[data-close]').forEach(x=>x.onclick=closeModal);$('#issueEdit').onsubmit=async e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.currentTarget));try{await api('/api/issues/'+encodeURIComponent(i.id),{method:'PATCH',body:JSON.stringify(o)});await refresh();closeModal();openIssue(i.id);toast('Назначение обновлено');}catch(err){toast(errorText(err));}};}
function errorText(err){const m={REQUIRED_REPORT_PHOTO:'В отчёте должно остаться хотя бы одно фото. Удалите только лишние снимки.',REQUIRED_INSPECTION_PHOTOS:'Для осмотра нужны минимум три фото объекта и фото каждого дефекта.',REQUIRED_PROBLEM_PHOTO:'Нельзя удалить последнее фото дефекта, найденного при осмотре.',BAD_EQUIPMENT_STATUS:'Выберите состояние оборудования',BAD_METRIC:'Расход должен быть числом от 0 до 1 трлн',METRIC_REQUIRED:'Заполните все три ресурса; если расхода нет, укажите 0',METRIC_PERIOD_EXISTS:'Показатели за этот месяц уже есть — отредактируйте существующую запись',BAD_INSPECTOR:'Сотруднику нужны доступ к объекту и права на просмотр и проведение осмотров',BAD_FREQUENCY:'Периодичность: целое число от 1 до 90 дней',BAD_DATE:'Укажите корректную дату',BAD_DATE_RANGE:'Дата окончания должна быть не раньше даты начала',BAD_AREA:'Площадь должна быть положительным числом',BAD_FLOOR:'Укажите целый этаж от −10 до 300',BAD_MONTH:'Выберите месяц расходов',BAD_COST:'Суммы должны быть от 0 до 1 трлн ₽',EXPENSE_PERIOD_EXISTS:'Расходы за этот месяц уже есть — откройте их для редактирования',TENANT_BUILDING_IMMUTABLE:'Объект арендатора нельзя менять: с ним связана история заявок',THREE_OR_FOUR_EXTERIOR_PHOTOS_REQUIRED:'Нужно приложить 3–4 фотографии объекта с разных сторон',TENANT_PROBLEM_DESCRIPTION_REQUIRED:'Опишите найденную проблему арендатора',TENANT_PROBLEM_PHOTO_REQUIRED:'К проблеме арендатора обязательно приложите фото',BUILDING_PROBLEM_PHOTO_REQUIRED:'К проблеме объекта обязательно приложите фото',PHOTO_REQUIRED:'Фото обязательно',REQUIRED_FIELDS:'Заполните обязательные поля',BAD_IMAGE_TYPE:'Выберите фотографию JPG, PNG или WEBP',IMAGE_TOO_LARGE:'Фотография слишком большая',BAD_RESPONSIBLE:'Сотрудник отключён или не имеет доступа к задачам этого объекта',BAD_TENANT:'Арендатор не относится к выбранному объекту',BAD_BUILDING:'Выберите действующий объект',USE_PHOTO_REPORT_WORKFLOW:'Закройте задачу через итоговый фотоотчёт',EMAIL_EXISTS:'Такой логин уже существует',PASSWORD_TOO_SHORT:'Пароль должен содержать не менее 10 символов',FORBIDDEN:'Недостаточно прав для этого действия',BUILDING_NAME_REQUIRED:'Укажите название объекта',BUILDING_MUST_BE_ARCHIVED:'Сначала переместите объект в архив',BUILDING_HAS_RELATED_DATA:'Нельзя удалить объект: к нему привязаны эксплуатационные записи'};if(err.name==='AbortError')return 'Сервер не ответил вовремя. Форма сохранена; повторите отправку.';if(err instanceof TypeError)return 'Нет связи с сервером. Данные формы сохранены; повторите попытку после подключения.';return m[err.code]||err.message||'Не удалось выполнить действие';}

let refreshPending=false,visibleRefreshBusy=false,lastVisibleRefresh=0;
async function refreshVisible(){
 if(!app.user||document.visibilityState==='hidden'||restoringSession)return;
 if(visibleRefreshBusy||$('#modal')||app.submittingForm||document.activeElement?.matches('input,textarea,select')){refreshPending=true;return;}
 if(Date.now()-lastVisibleRefresh<3000){refreshPending=true;setTimeout(refreshVisible,3100);return;}
 visibleRefreshBusy=true;refreshPending=false;const userId=app.user.id,view=app.view,scope=app.buildingScope;
 try{
  const updated=await refresh();lastVisibleRefresh=Date.now();if(!updated||app.user?.id!==userId)return;
  if($('#modal')||app.view!==view||app.buildingScope!==scope||document.activeElement?.matches('input,textarea,select')){refreshPending=true;return;}
  const scroll=window.scrollY,filters=$$('#view input[id],#view select[id]').map(e=>({id:e.id,value:e.value,checked:e.checked,type:e.type})),opened=$$('#view details').map(d=>d.open),tab=$('[data-attention][aria-pressed="true"]')?.dataset.attention;
  renderShell();for(const f of filters){const e=document.getElementById(f.id);if(e){e.value=f.value;e.checked=f.checked;e.dispatchEvent(new Event(f.type==='search'?'input':'change',{bubbles:true}));}}
  $$('#view details').forEach((d,n)=>d.open=!!opened[n]);if(tab)$(`[data-attention="${tab}"]`)?.click();window.scrollTo(0,scroll);
 }catch{refreshPending=true;}finally{visibleRefreshBusy=false;}
}
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')refreshVisible();});
document.addEventListener('focusout',()=>{if(refreshPending)setTimeout(refreshVisible,200);});
window.addEventListener('offline',()=>{document.body.classList.add('is-offline');toast('Нет связи. Заполненная форма остаётся открытой; повторите сохранение после подключения.');});
window.addEventListener('online',()=>{document.body.classList.remove('is-offline');toast('Связь восстановлена');refreshVisible();});
async function pollNotifications(){if(!app.user||document.visibilityState==='hidden')return;try{const userId=app.user.id,rows=await api('/api/notifications');if(app.user?.id!==userId)return;app.data.notifications=rows;const bell=$('#notificationsBtn');if(bell){const count=rows.filter(n=>!n.readAt).length;bell.innerHTML=`${bellIcon}${count?`<span>${count}</span>`:''}`;bell.setAttribute('aria-label',`Уведомления: ${count} непрочитанных`);}}catch{}}
setInterval(refreshVisible,60000);
boot();

